      "source": "2022年·数三·第2题",
      "content": "已知 $a_{n}=\\sqrt[n]{n}-\\frac{(-1)^{n}}{n}(n=1,2,\\cdots)$，则 $\\left\\{a_{n}\\right\\}$ （）",
      "answer": "A",
      "analysis": "考查知识点：数三 / 2022。 这道题的正确答案是 **A. 有最大值，有最小值**。",
      "solutionSteps": [
        "这道题考察的是数列的极限性质与有界性分析，非常经典。我们可以通过拆分奇偶项和分析极限来严谨地找出最值。",
        "### 详细解析",
        "已知数列通项公式为：\n$$\na_n = n^{\\frac{1}{n}} - \\frac{(-1)^n}{n}\n$$",
        "我们首先计算该数列的极限。已知当 $n \\to \\infty$ 时，$n^{\\frac{1}{n}} \\to 1$，且 $\\frac{(-1)^n}{n} \\to 0$。因此：\n$$\n\\lim_{n \\to \\infty} a_n = 1 - 0 = 1\n$$",
        "既然数列最终趋向于 $1$，我们以此为基准，分别考察数列的奇数项和偶数项与 $1$ 的大小关系。",
        "**1. 考察奇数项 ($n$ 为奇数)：**\n此时 $(-1)^n = -1$，通项变为：\n$$\na_n = n^{\\frac{1}{n}} + \\frac{1}{n}\n$$\n因为 $n \\ge 1$，显然 $n^{\\frac{1}{n}} \\ge 1$ 且 $\\frac{1}{n} > 0$。所以所有的奇数项 $a_n > 1$。\n特别地，当 $n=1$ 时：\n$$\na_1 = 1^1 + \\frac{1}{1} = 2\n$$",
        "**2. 考察偶数项 ($n$ 为偶数)：**\n此时 $(-1)^n = 1$，通项变为：\n$$\na_n = n^{\\frac{1}{n}} - \\frac{1}{n}\n$$\n我们来判断这些偶数项是否大于 $1$。令 $a_n > 1$，即：\n$$\nn^{\\frac{1}{n}} - \\frac{1}{n} > 1 \\implies n^{\\frac{1}{n}} > 1 + \\frac{1}{n}\n$$\n两边同时取 $n$ 次方：\n$$\nn > \\left(1 + \\frac{1}{n}\\right)^n\n$$\n我们知道数列 $(1 + \\frac{1}{n})^n$ 是单调递增的，且极限为自然常数 $e \\approx 2.718$。\n因此，当偶数 $n \\ge 4$ 时，不等式 $n \\ge 4 > e > (1 + \\frac{1}{n})^n$ 恒成立。这意味着对于所有 $n \\ge 4$ 的偶数项，都有 $a_n > 1$。",
        "唯一剩下的偶数项是 $n=2$ 时：\n$$\na_2 = \\sqrt{2} - \\frac{1}{2} \\approx 1.414 - 0.5 = 0.914 < 1\n$$",
        "### 结论汇总",
        "* **关于最小值**：通过上述分析可知，除了 $a_2$ 之外，数列的所有其他项（无论是奇数还是 $\\ge 4$ 的偶数）都严格大于 $1$。而 $a_2 \\approx 0.914 < 1$，因此 **$a_2$ 是该数列的最小值**。\n* **关于最大值**：我们考察函数 $f(x) = x^{\\frac{1}{x}}$，求导可知它在 $x=e$ 处取得最大值，因此在正整数中，$n=3$ 时该项最大（$3^{\\frac{1}{3}} \\approx 1.442$）。\n  对于任意 $n \\ge 3$ 的奇数项：$a_n \\le 3^{\\frac{1}{3}} + \\frac{1}{3} \\approx 1.442 + 0.333 = 1.775 < 2$。\n  对于任意偶数项：$a_n = n^{\\frac{1}{n}} - \\frac{1}{n} < n^{\\frac{1}{n}} \\le 3^{\\frac{1}{3}} \\approx 1.442 < 2$。\n  由此可见，当 $n \\ge 2$ 时，所有项都小于 $2$。因此，**$a_1 = 2$ 是该数列的最大值**。",
        "综上所述，该数列既有最大值 $a_1$，也有最小值 $a_2$，选 A。"
      ],
