        "第二步：比较g(x) = x 与h(x) = ex/10．把h 写成 ex/10 =  e1/10x = ax, a = e1/10 ≈1.105 > 1, 可见指数上的常数1 10 只是把底数换小了一点，h 仍是货真价实的指数函数。于是这是「幂比 指数」，由第二式 lim x→+∞ x ex/10 = lim x→+∞ x1 ax = 0, 所以x 充分大时g(x) < h(x)。 （想看这两式本身为什么成立，可以在学完洛必达法则之后自己验证：第一式令t = ln x 化为 lim t→+∞ t10 et ，连用10 次洛必达（每次都是∞ ∞型，分子降一次幂、分母不变）得 lim t→+∞ 10! et = 0； 第二式对 x ex/10 用一次洛必达得 lim x→+∞ ex/10 = 0。眼下把结论直接拿来用即可。）",
        "第三步：合并．x 充分大时 f(x) < g(x) < h(x), 即ln10 x < x < ex/10。故选(C)。 排除其他选项．(A) 说g < h < f、(B) 说h < g < f、(D) 说g < f < h，三者都把f = ln10 x 排在了g = x 的前面（更大），与第一步f g →0 矛盾；(A)(B) 还把指数量h 排在了f 之下， 与第二步矛盾。全部排除。 一句提醒：10 这个数字是烟幕弹．ln 的10 次方、指数上的1 10 都只是常数，不改变「等级」， 只是把「充分大」推得很远：解ln10 x = x（令t = ln x 即t = 10 ln t）得t ≈35.77，即x ≈ e35.77 ≈3.4×1015；解x = ex/10（即x = 10 ln x）同样得x ≈35.77。所以只有当x > 3.5×1015 左右时不等式链才真正成立——若拿x = 100 去试（此时ln10 100 ≈4.3 × 106 > 100）会得到 相反的印象，这正是本题的陷阱。"
