      "solutionSteps": [
        "四个函数在x = 0 处都有定义且连续，逐一用定义f′(0) = lim h→0 f(h) −f(0) h 检验（h 需分左 右）。",
        "(A) f(x) = |x| sin |x|——可导． 最快的办法是发现它其实不带绝对值：当x > 0 时|x| sin |x| = x sin x；当x < 0 时|x| = −x、 sin |x| = sin(−x) = −sin x，两个负号抵消，|x| sin |x| = (−x)(−sin x) = x sin x；x = 0 时两 边都是0。所以 f(x) ≡x sin x (∀x ∈R), 它是初等函数的乘积，处处可导，f′(0) = (sin x + x cos x)|x=0 = 0。 （也可直接算：|h| sin |h| h = sgn(h) sin |h| →0，左右一致。）",
        "(B) f(x) = |x| sin p |x|——可导． f(0) = 0， f(h) −f(0) h = |h| sin p |h| h = sgn(h) · sin p |h|. |sgn(h)| = 1 有界，而sin p |h| →sin 0 = 0，故「有界× 无穷小」给出 lim h→0 f(h) −f(0) h = 0, 左右极限都是0，f′(0) = 0，可导。（数值核对：h = ±10−5 时差商≈±3.16 × 10−3，确实在 往0 走。）",
        "(C) f(x) = cos |x|——可导． 余弦是偶函数，cos(−x) = cos x，所以cos |x| = cos x 对一切实数成立。绝对值形同虚设， f(x) ≡cos x 处处可导，f′(0) = −sin 0 = 0。",
        "(D) f(x) = cos p |x|——不可导． f(0) = cos 0 = 1。用cos u −1 ∼−u2 2 (u →0)，取u = p |h| →0，则 cos p |h| −1 ∼− p |h| 2 = −|h| 2 , 于是 f(h) −f(0) h = cos p |h| −1 h ∼ −|h| h = −1 2 sgn(h). L08 导数与微分 分别取极限： f′ +(0) = lim h→0+ cos √ h −1 h = −1 2, f′ −(0) = lim h→0− cos √ −h −1 h = lim h→0− −−h h = +1"
      ],
      "answer": "D",
      "pitfall": "含|x| 的题不要画图猜，用左右导数各算一遍：把x > 0 与x < 0 分别去掉绝对值，两个单\n侧极限相等才可导。经验结论：|x| · g(x) 在0 处可导⇔g(0) = 0；cos\np\n|x| 这种“偶函数套\np\n|x|”的，\np\n|x| 的尖点常常被平方消掉，反而可导——这是2018 那道题的全部机关。\n进阶。下面这道2015 数二3 是本节的天花板：它把“可导”“导函数连续”两件事放进同一个含\n参函数里，逼你分清f′(0) 存在与limx→0 f′(x) 存在的差别。（α = 2, β = 1 时就是那个著名的\nx2 sin 1\nx，可导但导函数不连续。）",
