      "content": "已知函数 $f(x)$ 在 $x=1$ 处可导，且\n$$\n\\lim_{x\\to0}\\frac{f\\bigl(e^{x^2}\\bigr)-3f\\bigl(1+\\sin^2x\\bigr)}{x^2}=2.\n$$\n求 $f'(1)$。",
