      "analysis": "考查知识点：数二 / 2022。 第一步：由题设极限求 $f(1)$。",
      "solutionSteps": [
        "由于题设极限为有限值，且 $x^2\\to0$，所以\n$$\n\\lim_{x\\to0}\\left[\nf\\bigl(e^{x^2}\\bigr)-3f\\bigl(1+\\sin^2x\\bigr)\n\\right]=0.\n$$\n又因为 $f(x)$ 在 $x=1$ 处可导，所以在该点连续。令 $x\\to0$，得\n$$\nf(1)-3f(1)=0,\n$$\n从而 $f(1)=0$。",
        "第二步：利用导数定义计算两个极限。",
        "由导数定义及 $e^{x^2}-1\\sim x^2$，得\n$$\n\\begin{aligned}\n&\\lim_{x\\to0}\\frac{f(e^{x^2})}{x^2}\\\\\n&=\\lim_{x\\to0}\n\\frac{f(e^{x^2})-f(1)}{e^{x^2}-1}\n\\cdot\\frac{e^{x^2}-1}{x^2}\\\\\n&=f'(1).\n\\end{aligned}\n$$\n同理，由 $\\sin^2x\\sim x^2$，得\n$$\n\\begin{aligned}\n&\\lim_{x\\to0}\\frac{f(1+\\sin^2x)}{x^2}\\\\\n&=\\lim_{x\\to0}\n\\frac{f(1+\\sin^2x)-f(1)}{\\sin^2x}\n\\cdot\\frac{\\sin^2x}{x^2}\\\\\n&=f'(1).\n\\end{aligned}\n$$",
        "第三步：代入题设极限。",
        "由上面两个极限，\n$$\nf'(1)-3f'(1)=2.\n$$\n因此\n$$\n\\boxed{f'(1)=-1}.\n$$"
      ],
      "pitfall": "注意审题条件与运算符号，规避常见计算失误。",
