      "analysis": "（I）由极限的保号性造出一个f < 0 的点，再用零点定理。\n（II）关键一眼：ff′′ +(f′)2 = (ff′)′，\n于是问题变成「函数g = ff′ 的导数有两个零点」，即「g 有三个零点」。",
