        "第一步：认出待证方程左端是一个乘积的导数．注意  f(x)f′(x) ′ = f′(x)f′(x) + f(x)f′′(x) = f(x)f′′(x) +  f′(x) 2 , 恰是待证方程的左端。于是令 g(x) = f(x)f′(x) , g′(x) = f(x)f′′(x) +  f′(x) 2 . f 在[0, 1] 上有二阶导数，故f, f ′ 在[0, 1] 上都可导（从而连续），g 在[0, 1] 上可导。问题转 化为：证明g′ 在(0, 1) 内至少有两个不同零点。而由罗尔定理，只要g 在[0, 1] 上有三个不 同零点即可。"
