      "analysis": "（I）奇函数必有f(0) = 0，直接拉格朗日。（II）出现「f′′ + f′」这种导数的线性组合，一律\n用积分因子ex 打包成[ex (f′ −1)]′；再用「奇函数的导数是偶函数」造出罗尔定理需要的两\n个相等端点值。",
      "solutionSteps": [
        "（I） f 为[−1, 1] 上的奇函数，即f(−x) = −f(x)。取x = 0 得f(0) = −f(0)，故 f(0) = 0. f 在[−1, 1] 上有二阶导数，因而在[0, 1] 上连续、在(0, 1) 内可导。由拉格朗日中值定理，存 在ξ ∈(0, 1)，使 f′(ξ) = f(1) −f(0) 1 −0 = 1 −0 = 1. （I）证毕。 （II）",
        "第一步：辅助函数是怎么想出来的． 要证的是「存在η 使f′′(η) + f′(η) −1 = 0」。证「某点导数为零」的标准武器是罗尔定理， 所以要把f′′ + f′ −1 写成某个函数的导数。 直接看：(f′(x) −1)′ = f′′(x)，还差一个f′(x)。这是常微分方程里的经典情形——形如y′ + y 的组合，乘上积分因子ex 就能凑成全导数： ex  f′′(x) + f′(x) −1  = exf′′(x) + exf′(x) −ex =  exf′(x) −ex′ = h ex f′(x) −1  i′ . 于是令 F(x) = ex f′(x) −1  , F ′(x) = ex  f′′(x) + f′(x) −1  . 因为ex > 0 恒成立，所以F ′(η) = 0 ⇐⇒f′′(η) + f′(η) = 1。现在只需给F 找两个函数值 相等的点。 F 的零点就是f′(x) = 1 的点。（I）已经给了一个：x = ξ ∈(0, 1)，即F(ξ) = 0。还需要第二 个——这时用上「f 是奇函数」这个尚未用足的条件：对f(−x) = −f(x) 两边求导， −f′(−x) = −f′(x) =⇒ f′(−x) = f′(x), 即f′ 是偶函数。于是f′(−ξ) = f′(ξ) = 1，F(−ξ) = 0。两个零点到手。",
        "第二步：正式书写证明． 由f 为奇函数且在[−1, 1] 上可导，对f(−x) = −f(x) 两边关于x 求导得−f′(−x) = −f′(x)， 即f′ 在[−1, 1] 上是偶函数。结合（I）， f′(−ξ) = f′(ξ) = 1, ξ ∈(0, 1), −ξ ∈(−1, 0). 令 F(x) = ex f′(x) −1  , x ∈[−1, 1]. 由题设f 有二阶导数，故f′ 在[−1, 1] 上可导（从而连续），F 在[−1, 1] 上可导，且 F ′(x) = ex f′(x) −1  + exf′′(x) = ex  f′′(x) + f′(x) −1  . 又 F(−ξ) = e−ξ f′(−ξ) −1  = e−ξ · 0 = 0, F(ξ) = eξ f′(ξ) −1  = 0. 由ξ ∈(0, 1) 知−ξ < ξ，区间[−ξ, ξ] ⊂(−1, 1) 非退化。F 在[−ξ, ξ] 上连续、在(−ξ, ξ) 内 可导、F(−ξ) = F(ξ)，由罗尔定理，存在 η ∈(−ξ, ξ) ⊂(−1, 1), F ′(η) = 0, 即eη [f′′(η) + f′(η) −1] = 0。因eη ̸= 0，故 f′′(η) + f′(η) = 1. （II）证毕。 具体例子核验．取f(x) = x（奇函数，f(1) = 1，二阶可导）。（I）中f′ ≡1，任意ξ ∈ (0, 1) 都行；（II）中f′′ + f′ = 0 + 1 = 1 对一切η 成立✓再取f(x) = sin πx 2 （奇函 数，f(1) = 1）：f′(x) = π 2 cos πx 2 ，由f′(ξ) = 1 得cos πξ 2 = 2 π，ξ ≈0.5607 ∈(0, 1)；而 f′′(η) + f′(η) = −π2 4 sin πη 2 + π 2 cos πη 2 在η = −ξ 处取值π2 4 sin πξ 2 + 1 > 1，在η = ξ 处取 值1 −π2 4 sin πξ 2 < 1，由连续性它在(−ξ, ξ) 内确实取到1 ✓"
      ],
      "answer": "详见具体步骤解析",
      "pitfall": "表要竖着背：左列是你在卷面上会看见的，右列是你要写下的第一行。五条套路里第一、第二\n条命中了本讲全部的构造题，先把这两条练成条件反射，剩下三条各花两分钟看懂即可。\n顺带说清柯西：三个中值定理里，柯西2010–2026 在本讲一次都没有单独命过题。它的识别\n信号仍要记住——结论里出现ln x、ex 这种与f 无关的“多余函数”，且形如f(b)−f(a)\ng(b)−g(a) ，就把\n那个多余的函数取作g。知道这一条即可，不必为它专门刷题。\n两道不靠构造的硬题\n真题演练（估计型，数一19 ／数三19，难度4）。结论不是等式而是不等式估计|f′(ξ)| ≥M\n——推理链第1 步就把后面的路定死了：只有一阶导、而且是估计，不用造F，要做的是把区间\n切到合适的长度再用拉格朗日：",
