      "questionNumber": "(19)",
      "content": "集10.5）★★★★☆\n设函数f(x) 在区间[0, 2] 上具有连续导数，f(0) = f(2) = 0，M = max\nx∈[0,2]{|f(x)|}，证明：\n(I) 存在ξ ∈(0, 2)，使得|f′(ξ)| ≥M；\n(II) 若对任意的x ∈(0, 2)，|f′(x)| ≤M，则M = 0.",
      "analysis": "（I）在最值点把区间劈成两段，哪一段短就在哪一段上用拉格朗日中值定理——因为差商\nM\n段长\n的分母越小、结果越大。（II）反证：|f′| ≤M 把（I）的不等式逼成等号，逼出f 必是折线\ny = Mx 与y = M(2 −x)，而折线在x = 1 处f′ 不连续，与「f 有连续导数」矛盾。",
      "solutionSteps": [
        "（I）证明存在ξ ∈(0, 2) 使|f′(ξ)| ≥M． f 在[0, 2] 上连续，故|f| 在[0, 2] 上连续，最大值M = max x∈[0,2] |f(x)| 可以取到：存在c ∈[0, 2] 使|f(c)| = M。 情形0：M = 0．此时f ≡0，任取ξ ∈(0, 2) 都有|f′(ξ)| = 0 ≥0 = M，结论成立。 以下设M > 0。由f(0) = f(2) = 0 知c ̸= 0 且c ̸= 2，故c ∈(0, 2)。c 与区间中点1 比较， 分两种情形（两段中至少有一段长度≤1）： 情形1：0 < c ≤1．f 在[0, c] 上连续、在(0, c) 内可导，由拉格朗日中值定理，存在ξ ∈ (0, c) ⊂(0, 2)，使 f′(ξ) = f(c) −f(0) c −0 = f(c) c =⇒ f′(ξ) = |f(c)| c = M c ≥M 1 = M （用了0 < c ≤1 与M > 0）。 情形2：1 < c < 2．f 在[c, 2] 上连续、在(c, 2) 内可导，由拉格朗日中值定理，存在ξ ∈ (c, 2) ⊂(0, 2)，使 f′(ξ) = f(2) −f(c) 2 −c = −f(c) 2 −c =⇒ f′(ξ) = M 2 −c > M 1 = M （用了0 < 2 −c < 1）。 两种情形都得到ξ ∈(0, 2) 使|f′(ξ)| ≥M。（I）证毕。 （II）设对任意x ∈(0, 2) 有|f′(x)| ≤M，证明M = 0． 用反证法：假设M > 0。仍取c ∈(0, 2) 使|f(c)| = M。",
        "第一步：最值点只能是c = 1．把（I）的两段估计同时用上。在[0, c] 上，存在ξ1 ∈(0, c) 使 |f′ (ξ1)| = M c ；在[c, 2] 上，存在ξ2 ∈(c, 2) 使|f′ (ξ2)| = M 2 −c。由假设|f′| ≤M 于(0, 2)， 得 M c ≤M =⇒c ≥1, M 2 −c ≤M =⇒2 −c ≥1 =⇒c ≤1. （两处都用了M > 0 可以约去。）故c = 1，即 |f(1)| = M. 不妨设f(1) = M > 0；否则以−f 代替f，题设条件（连续导数、f(0) = f(2) = 0、max |f| = M、 |f′| ≤M）全部不变，结论也不变。",
        "第二步：逼出f 的具体形状．先看[0, 1]。取任意x ∈(0, 1)。 在[0, x] 上用拉格朗日中值定理：存在s ∈(0, x) 使f(x) −f(0) = f′(s)x，故 f(x) = f′(s) x ≤ f′(s) x ≤Mx. 在[x, 1] 上用拉格朗日中值定理：存在t ∈(x, 1) 使f(1) −f(x) = f′(t)(1 −x)，故 M −f(x) = f′(t)(1 −x) ≤M(1 −x) =⇒ f(x) ≥M −M(1 −x) = Mx. 两个不等式夹出 f(x) = Mx, ∀x ∈[0, 1] （x = 0, 1 处直接验证也成立）。求导得 f′(x) = M, ∀x ∈(0, 1). 同理看[1, 2]。取任意x ∈(1, 2)。在[1, x] 上：存在s ∈(1, x) 使f(x) −M = f′(s)(x −1) ≥ −M(x −1)，故f(x) ≥M(2 −x)。在[x, 2] 上：存在t ∈(x, 2) 使f(2) −f(x) = f′(t)(2 −x)， 即−f(x) = f′(t)(2 −x) ≥−M(2 −x)，故f(x) ≤M(2 −x)。两者夹出 f(x) = M(2 −x), ∀x ∈[1, 2], 从而 f′(x) = −M, ∀x ∈(1, 2).",
        "第三步：在x = 1 处产生矛盾．上一步表明f 在x = 1 附近是一条「屋脊形」折线。由f(x) = Mx （x ≤1）得左导数f′ −(1) = M；由f(x) = M(2 −x)（x ≥1）得右导数f′ +(1) = −M。而题 设f 在[0, 2] 上具有连续导数，f 在x = 1 处可导，左右导数必须相等： M = f′ −(1) = f′ +(1) = −M =⇒ 2M = 0 =⇒ M = 0, 与假设M > 0 矛盾。（若改用「f′ 连续」来说：lim x→1−f′(x) = M 而lim x→1+ f′(x) = −M，f′ 在 1 处没有极限，同样矛盾。） 故假设不成立，必有 M = 0. （II）证毕。此时f ≡0。 临界例子（说明M = 0 的结论有多「紧」）．折线f(x) =    Mx, 0 ≤x ≤1, M(2 −x), 1 < x ≤2 满足 f(0) = f(2) = 0、max |f| = M、在x ̸= 1 处|f′| = M，唯独在x = 1 处不可导。可见「f 有 连续导数」这个条件正是用来排除这个反例的，一个字都不能少✓"
      ],
      "answer": "详见具体步骤解析",
      "pitfall": "第(I) 问的钥匙是在最值点把[0, 2] 劈成两段，挑短的那一段用拉格朗日：差商\nM\n段长的分母\n越小结果越大，而两段里必有一段长度不超过1。第(II) 问用反证：若处处|f′| ≤M，(I) 的\n不等式被逼成等号，f 只能是y = Mx 与y = M(2 −x) 拼成的折线，而折线在x = 1 处f′\n不连续，与“f 有连续导数”矛盾，故M = 0。\n两条通用经验：结论是不等式估计时，先找最值点把区间切开；条件里“连续导数”这四个字\n出现时，它八成是留着最后用来制造矛盾的。\n天花板题（2025 数一19 ／数二21 ／数三20，三卷同题，难度5）。本讲17 年最难的一道，\n也是唯一一道充要条件型证明。必要性用两次拉格朗日；充分性要靠“差商夹逼+ 取极限”。特\n别注意：题目只给了可导，没给二阶可导，所以全程不许写f′′——这一条正是推理链第3 步“检\n查条件”的极端版本：",
