        "第二步：找驻点．y′ = 0 当且仅当分子为零： y2 + 2xy = 0 ⇐⇒y(y + 2x) = 0 ⇐⇒y = 0 或y = −2x. 这只是必要条件，还必须同时满足原方程(∗)，所以联立讨论： 情形1：y = 0．代入(∗) 得0 + 0 + 0 + 6 = 6 ̸= 0，无解。舍去。 情形2：y = −2x．代入(∗)： (−2x)3 + x(−2x)2 + x2(−2x) + 6 = −8x3 + 4x3 −2x3 + 6 = −6x3 + 6 = 0, 即x3 = 1，故x = 1（实根唯一），相应y = −2。 校验(1, −2) 确在曲线上：(−2)3 + 1 · (−2)2 + 12 · (−2) + 6 = −8 + 4 −2 + 6 = 0 ✓ 所以唯一的驻点是x = 1，f(1) = −2。",
        "第三步：定极值类型（求y′′）．对(∗∗) 两边再对x 求导： 6yy′ + 2y + 2xy′ + 2x  y′ + 3y2 + 2xy + x2 y′′ + 2yy′ + 2y + 2xy′ = 0. 在驻点处y′ = 0，含y′ 的项全部消失，上式化为 3y2 + 2xy + x2 y′′ + 2y = 0 =⇒ y′′ = − 2y 3y2 + 2xy + x2 . （更快的做法：对y′ = − y2 + 2xy 3y2 + 2xy + x2 用商的求导法则，在y′ = 0 处分子为零，故分母的导 数那一项不起作用，只需对分子求导： y2 + 2xy ′ = 2yy′ + 2y + 2xy′ y′=0 −−−→2y，结论相同。） 代入x = 1、y = −2：分母= 3 · 4 + 2 · 1 · (−2) + 1 = 12 −4 + 1 = 9，故 y′′ x=1 = −2 · (−2) = 4 9 > 0. 由极值第二充分条件，x = 1 是f 的极小值点。 答案．f(x) 有唯一极值：极小值f(1) = −2（无极大值）。 验算．在x = 1 附近取x = 1.1，解y3 + 1.1y2 + 1.21y + 6 = 0 得实根y ≈−1.99773；取 x = 0.9 得实根y ≈−1.99783。两侧都大于−2，中间f(1) = −2 最小✓且由y′′ = 4 9 估计 f(1 ± 0.1) ≈−2 + 1 2 · 4 9 · 0.01 = −2 + 0.00222，与数值解−1.9977 吻合✓"
