      "content": "设函数f(x) 具有2 阶导数，g(x) = f(0)(1 −x) + f(1)x，则在区间[0, 1] 上\n(A) 当f′(x) ≥0 时，f(x) ≥g(x)\n(B) 当f′(x) ≥0 时，f(x) ≤g(x)\n(C) 当f′′(x) ≥0 时，f(x) ≥g(x)\n(D) 当f′′(x) ≥0 时，f(x) ≤g(x)",
      "analysis": "认出g(x) = f(0)(1 −x) + f(1)x 就是过两端点(0, f(0))、(1, f(1)) 的弦。曲线在弦的哪一侧，\n由凹凸性（f′′ 的符号）决定，与单调性（f′）无关。",
