        "（I）设 fn(x) = x + x2 + · · · + xn −1, n ≥2. 方程即fn(x) = 0。 唯一性（至多一根）．在 1 2, 1  上 f′ n(x) = 1 + 2x + 3x2 + · · · + nxn−1 > 0 （每一项在x > 0 时都为正），故fn 在 1 2, 1  上严格单调递增，至多一个零点。 存在性（至少一根）．fn 是多项式，在 1 2, 1  上连续。左端点用等比数列求和： n X k=1 1 k = 2  1 − 1 n 1 −1 = 1 − 1 n , 所以 fn 1  = 1 − 1 n −1 = −1 2n < 0. 右端点 fn(1) = 1 + 1 + · · · + 1 | {z } n 项 −1 = n −1 > 0 (n ≥2). 两端异号，由零点定理，fn 在 1 2, 1  内至少有一个零点。 综合两条：方程xn + xn−1 + · · · + x = 1 在 1 2, 1  内有且仅有一个实根，记为xn。 （II）分两步：先证{xn} 收敛，再求极限。",
        "第一步：证{xn} 单调递减且有下界． L15 不等式证明与方程根的个数 关键手法是把下一个函数在这一个根处的值算出来。由定义 fn+1(x) = fn(x) + xn+1, 在x = xn 处取值（注意fn (xn) = 0，且xn > 1 2 > 0）： fn+1 (xn) = 0 + x n+1 n > 0. 而fn+1 (xn+1) = 0。由（I）的论证，fn+1 在 1 2, 1  上严格单调递增，从fn+1 (xn) > 0 = fn+1 (xn+1) 立得 xn > xn+1. 故{xn}n≥2 严格单调递减；又由（I）恒有xn > 1 2，有下界。由单调有界准则，lim n→∞xn 存在， 记为A，且A ≥1 2。",
        "第二步：求A． 把xn 满足的方程用等比求和化简。因0 < xn < 1（分母1 −xn ̸= 0）， xn + x2 n + · · · + x n n = xn (1 −x n n ) 1 −xn = 1. 去分母：xn −x n+1 n = 1 −xn，整理得关键恒等式 2xn −1 = x n+1 n . 现在只需说明右端趋于0。由第一步的单调递减性，对一切n ≥2 有 2 < xn ≤x2 < 1. 记q = x2，这是一个与n 无关的常数，且0 < q < 1（事实上x2 满足x2 + x −1 = 0，即 q = √ 5 −1 ≈0.618）。于是 0 < x n+1 n ≤q n+1 n→∞ −−−−−→0, 由夹逼准则lim n→∞x n+1 n = 0。对恒等式两边取极限： 2A −1 = 0 =⇒ A = 1",
