      "pitfall": "（1）数根三步法：求f′ 定单调区间→算各分界点的函数值（极值）与两端极限→在每个单\n调区间上用零点定理，「两端异号则恰一根，同号则无根」。单调区间的个数就是根个数的上\n界。\n（2）f 为奇函数且f(0) = 0 时，根的个数一定是奇数；只需数正根，总数= 2 × (正根数) + 1。\n（3）常用界：|arctan x| < π\n2 ，故k arctan x −x 在x →±∞时由−x 主导，极限为∓∞。凡\n「有界函数+ 无界主项」都可这样判断。\n（4）不等式arctan x < x (x > 0)、arctan x > x (x < 0) 是本题k = 1 情形的直接来源，值得\n背下来。\n易错\n（1）只讨论k > 0，漏掉k ≤0。虽然k ≤0 的结论与0 < k ≤1 相同，但答题时必须覆盖全\n部k ∈R。\n（2）临界值k = 1 归错类。k = 1 时f′(x) =\n−x2\n1 + x2 ≤0，只在一点为零，仍是严格单调递减，\n故只有1 个根；若误以为「f′ 有零点就有极值」会数成3 个。\n（3）忘掉x = 0 这个恒有的根，只报「k > 1 时有2 个根」。\n（4）用图像法（画y = k arctan x 与y = x 交点）时只凭「切于原点」估计，必须落实为\nk =\nx\narctan x\nx→0 = 1 这个分界，否则临界值说不清楚。\n（5）把\nlim\nx→+∞f(x) 误算成+∞（错在以为k arctan x 会跑到无穷）。\n不等式证明：四条路线\n先按题面选路，再动笔\n不等式证明的路线只有四条，而选哪条完全由题面的形状决定，不需要试：\n• 题面含的是两个端点的值（不等式两边都是具体表达式，一个变量）⇒路线一：作差构\n造函数，再接路线二。\nL15\n不等式证明与方程根的个数\n• 题面含f(b) −f(a) 这样的差式（或两个变量之差）⇒路线三：中值定理。\n• 题面给了二阶导的信息（f′′ > 0、|f′′| ≤M）⇒路线四：泰勒（或凹凸性）。\n三条判据互不重叠，看一眼题面就能定。本讲3 道不等式真题全部走第一、二条，第三、四\n条的题都归在L10、L12，所以复习本节时把力气押在作差构造上是正确的。\n定理/ 公式15.3 四条路线\n1. 作差构造函数：把待证式全部移到一边，令F = 左−右，问题变成“证F ≥0”。这是一\n切的第一步，构造出来的F 决定后面好不好走。\n2. 单调性／极值：证F 单调且端点值≥0；F 不单调时改求F 的最小值并证它≥0。若F ′\n符号不明，就对F ′ 再用一次，可以反复求导直到符号清楚，然后逐层倒推回去（每一层\n都要交代那一层的端点值）。\n3. 中值定理：待证式里出现f(b) −f(a) 时，用拉格朗日换成f′(ξ)(b −a)，再估计f′ 的范\n围。\n4. 泰勒：已知f′′ 的符号或界时，在适当点展开，用余项的符号或估计收尾（见L12）；f′′ > 0\n时也可以直接引用凹凸性的两条图像语言（弦上／切线上，见L14）。\n怎么从目标反推出要构造的函数\n下面这道要证的是一个只含一个变量的不等式。倒推链只有三环：\n1. 目标是“左≥右”，能用的工具是“单调函数的端点值”，所以必须先有一个函数和一个\n端点——作差令F = 左−右，并找出那个让F = 0 的点（这里是x = 0）。\n2. 构造完先别急着求导，看F 的奇偶性：F 是偶函数就只需证x ≥0 那一半，工作量立刻\n减半。这一步很多人不做。\n3. 再求F ′。若F ′ 的符号一眼可见，收工；看不出来就对F ′ 重复第1 步的想法——F ′(0) 是\n多少、F ′′ 的符号如何。\n“作差→找零点→看奇偶→求导”，这四个动作的顺序对所有一元不等式都成立。\n真题演练（2012 数一15 ／数二20 ／数三18，三卷同题）。本讲唯一一道三卷通吃的题，也\n是数一17 年在这一讲里仅有的两道之一：",
