      "analysis": "「根式+ 反三角」的不定积分：先令t = √ex −1 一举去掉根号与指数，化为多项式乘arctan t，\n再分部积分；最后回代时用完全平方把式子收拢。",
      "solutionSteps": [
        "第一步：定义域与换元．要求ex −1 ≥0，即x ≥0。令 t = √ ex −1 (t ≥0) =⇒ex = t2 + 1, x = ln t2 + 1  , dx = 2t t2 + 1 dt. 又e2x = (ex)2 = t2 + 1 2，于是 ˆ e2x arctan √ ex −1 dx = ˆ t2 + 1 2 arctan t · 2t t2 + 1 dt = 2 ˆ t t2 + 1  arctan t dt = ˆ 2t3 + 2t  arctan t dt. 根号没有了，剩下的是「多项式× 反三角」，标准分部积分。 L16 不定积分：换元与分部的决策树",
        "第二步：分部积分．取u = arctan t，dv = 2t3 + 2t  dt，则v = t4 2 + t2，du = dt 1 + t2 ： ˆ 2t3 + 2t  arctan t dt = t4 2 + t2  arctan t − ˆ t4 2 + t2 1 + t2 dt.",
        "第三步：算剩下的有理积分．关键是注意t4 + 2t2 = t2 + 1 2 −1，于是 t4 2 + t2 1 + t2 = t4 + 2t2 2 (1 + t2) = t2 + 1 2 −1 2 (1 + t2) = 1  t2 + 1 − 1 + t2  , 从而 ˆ t4 2 + t2 1 + t2 dt = 1 t3 3 + t −arctan t  + C = t3 6 + t 2 −arctan t + C. 代回： ˆ 2t3 + 2t  arctan t dt = t4 2 + t2 + 1  arctan t −t3 6 −t 2 + C.",
        "第四步：回代并化简．注意括号里正是一个完全平方的一半： t4 2 + t2 + 1 2 = t2 + 1 2 = e2x 2 . 又t = √ex −1，t3 = (ex −1)3/2，把后两项提公因式√ex −1： t3 6 + t 2 = √ex −1 [(ex −1) + 3] = (ex + 2) √ex −1 . 所以 ˆ e2x arctan √ ex −1 dx = e2x 2 arctan √ ex −1 −1 6 (ex + 2) √ ex −1 + C",
        "第五步：求导验算．记t = √ex −1，则t′ = ex 2√ex −1，1+t2 = ex，故(arctan t)′ = t′ 1 + t2 = 2√ex −1。于是 e2x 2 arctan t ′ = e2x arctan t + e2x 2 · 2√ex −1 = e2x arctan t + e2x 4√ex −1,  −(ex + 2) √ex −1 ′ = −1  ex√ ex −1 + (ex + 2) · ex 2√ex −1  = − ex 12√ex −1 [2 (ex −1) + ex + 2] = − ex · 3ex 12√ex −1 = − e2x 4√ex −1. 两式相加，非arctan 的项恰好抵消，得e2x arctan √ex −1，与被积函数一致，✓。（另在 x = 0.5, 1, 2 处作数值求导核对，误差量级10−16。） L16 不定积分：换元与分部的决策树"
      ],
