        "第一步：凑黎曼和．把1 n2 拆成1 n · 1 n，用其中一个1 n 把k 变成k n： n X k=1 k n2 ln  1 + k n  = 1 n n X k=1 k n ln  1 + k n  . 求和号内每一项只通过k n 出现，形状已经对了。",
        "第二步：按定积分定义取极限．令f(x) = x ln(1 + x)。因为1 + x ≥1 > 0，f 在[0, 1] 上连 续，故可积。把[0, 1] 等分成n 份，∆x = 1 n，第k 个小区间取右端点ξk = k n，上式即黎曼 和 n X k=1 f(ξk)∆x，故 lim n→∞ n X k=1 k n2 ln  1 + k n  = ˆ 1 x ln(1 + x) dx.",
        "第三步：分部积分．把x dx 凑成d x2  。这里有个小技巧：凑原函数时取x2 −1 比取x2 更省事，因为x2 −1 = (x + 1)(x −1) 能与1 + x 约分。两种做法都写一下。 做法一（常规）． ˆ 1 x ln(1 + x) dx = ˆ 1 ln(1 + x) d x2  = x2 2 ln(1 + x) 1 − ˆ 1 x2 2 · 1 + x dx = 1 2 ln 2 −1 ˆ 1 x2 1 + x dx. 对最后的积分作多项式除法：x2 1 + x = x−1+ 1 + x（验证：(x−1)(1+x)+1 = x2−1+1 = x2， ✓）。于是 ˆ 1 x2 1 + x dx = x2 2 −x + ln(1 + x) 1 = 1 2 −1 + ln 2 = ln 2 −1",
        "2. 代回： ˆ 1 x ln(1 + x) dx = 1 2 ln 2 −1  ln 2 −1  = 1 2 ln 2 −1 2 ln 2 + 1 4 = 1",
        "4. 做法二（凑x2 −1 ）． ˆ 1 x ln(1 + x) dx = ˆ 1 ln(1 + x) d x2 −1  = x2 −1 ln(1 + x) 1 − ˆ 1 x2 −1 · 1 + x dx. 边界项在x = 1 处为0 · ln 2 = 0，在x = 0 处为 −1  ln 1 = 0，整项为0；而x2 −1 1 + x = x −1， 所以 ˆ 1 x ln(1 + x) dx = −1 ˆ 1 (x −1) dx = −1 x2 2 −x 1 = −1 1 2 −1  = 1"
