        "第二步：写出直线AB 与区域D． 注意题目说的是区域D 由曲线L 与直线AB 围成，AB 是连接A e2, 2  与B(1, 0) 的弦（不 是上面那条切线）。其斜率为 k = 2 −0 e2 −1 = e2 −1, AB : y = 2 (x −1) e2 −1 , 1 ≤x ≤e2. 因为(ln x)′′ = −1 x2 < 0，y = ln x 是凸（上凸）的，所以在两交点之间曲线在弦的上方： ln x ≥2 (x −1) e2 −1 , 1 ≤x ≤e2, 且两端取等号。故 D =  (x, y) 1 ≤x ≤e2, 2(x −1) e2 −1 ≤y ≤ln x  , 它整个位于x 轴上方（y ≥0），这一点决定了下一问可以直接用圆环法。",
        "第三步：求面积． S = ˆ e2  ln x −2(x −1) e2 −1  dx. 分项计算。第一项用分部积分（ ˆ ln x dx = x ln x −x + C）： ˆ e2 ln x dx = [x ln x −x]e2 1 = 2e2 −e2 −(0 −1) = e2 + 1. 第二项其实是以B(1, 0)、A e2, 2  、 e2, 0  为顶点的直角三角形的面积1 e2 −1  ·2 = e2 −1， 也可直接积： e2 −1 ˆ e2 (x −1) dx = e2 −1 · (x −1)2 e2 = e2 −1 · e2 −1 2 = e2 −1. 所以 S = e2 + 1  − e2 −1  = 2. 面积竟是常数2，与e 无关，是本题的漂亮之处。",
