      "questionNumber": "(17)",
      "content": "为了实现利润最大化，厂商需要对某商品确定其定价模型. 设Q 为该商品的需求量，p 为价\n格，MC 为边际成本，η 为需求弹性(η > 0).\n(I) 证明定价模型为p = MC\n1 −1\nη\n；\n(II) 若该商品的成本函数为C(Q) = 1 600 + Q2，需求函数为Q = 40 −p，试由（I）中的定\n价模型确定此商品的价格.",
