      "pitfall": "这道题里的关键不等式是ln(1 + t) < t (t > 0)，它由φ(t) = t −ln(1 + t) 单调递增得来。\n积分不等式的难点几乎从不在积分，而在那个被积函数的初等不等式。把L15 里常用的几条\n（ln(1 + t) < t、sin t < t、et ≥1 + t）背熟，这一类题就打开了一半。\n另一个容易丢分的细节：由0 < u < v 推un < vn 时必须说明两端为正，否则n 为偶数时不\n等号会翻转。阅卷按步给分，这一句值分。\n真题演练（习题23.2，走路线二：把积分对象构造成函数）。2014 年数二19、数三19 同题。怎\n么从目标反推：待证式的积分上限里套着另一个变限积分，两端根本不在同一个区间上，路线一\n无处下手；于是把不等式移项写成“某个式子≥0”，再把其中一个端点放成变量x，得到F(x)，\n问题就变成“证F 从0 出发一路不降”——这是L10 构造辅助函数的老套路：",
