      "content": "微分方程2yy′ −y2 −2 = 0 满足条件y(0) = 1 的特解y =\n.",
      "analysis": "方程里只出现yy′ 与y2，说明真正的未知函数是u = y2：因为u′ = 2yy′，换元后立刻变成\n一阶线性（且可分离）方程．",
      "solutionSteps": [
        "法二（直接分离变量）．把方程写成2y dy\ny2 + 2 = dx，左端分子恰是分母的微分：d(y2+2) = 2y dy，\n故\nln\ny2 + 2\n\n= x + C1 =⇒y2 + 2 = Cex,\n与上面一致；由y(0) = 1 得C = 3．\n验证．取y = √3ex −2，则y2 = 3ex −2，两边对x 求导得2yy′ = 3ex；而y2 + 2 = 3ex．故\n2yy′ −y2 −2 = 3ex −3ex = 0，方程满足；又y(0) = √3 −2 = 1，初值满足．"
      ],
      "answer": "√3ex −2",
      "pitfall": "形如y′ = f(x)y + g(x)y−1（即伯努利方程n = −1）或只含yy′ 与y2 的方程，统一用代换\nu = y2、u′ = 2yy′ 化为关于u 的一阶线性方程．一阶线性方程u′ + p(x)u = q(x) 的通解公\n式：u = e−\n´\np dx ´\nqe\n´\np dx dx + C\n\n．\n易错\n最常见的失分点是把答案写成y = ±√3ex −2——初值问题的解是唯一的一支，必须由y(0) =\n1 > 0 舍去负号．其次是把2yy′ 误当作(2y)′ 或\ny2′ 的一半时算错系数：\ny2′ = 2yy′，不\n带额外因子．\n真题演练（习题24.1，一阶线性的标准形态）。y′+y = e−x cos x 已经是标准形，P = 1、Q = e−x cos x，\n套一次公式就到底——这是本讲出现频率最高的一个动作：",
      "difficulty": "★★☆☆☆",
      "verified": true,
      "source": "Maki大串讲 真题24.1"
