      "category": "数一",
      "questionNumber": "(10)",
      "content": "24.1）★★☆☆☆\n微分方程y′ + y = e−x cos x 满足条件y(0) = 0 的解为y =\n.",
      "analysis": "一阶线性方程y′ + P(x)y = Q(x) 的求解。本题积分因子恰好把右端的e−x 消掉，方程化成\n「导数等于cos x」，一步积分即可。",
      "solutionSteps": [
        "方程y′ + y = e−x cos x 是一阶线性非齐次方程，P(x) = 1，Q(x) = e−x cos x。",
        "第一步：乘积分因子。取 µ(x) = e ´ P(x) dx = e ´ 1 dx = ex. 两边同乘ex（ex > 0，不会丢解也不会增根）： exy′ + exy = ex · e−x cos x = cos x. 左端正是乘积的导数：(exy)′ = exy′ + exy，于是 (exy)′ = cos x. L24 一阶微分方程",
        "第二步：积分。 exy = ˆ cos x dx = sin x + C, 故通解为 y = e−x (sin x + C) .",
        "第三步：定常数。代入y(0) = 0： 0 = e0 (sin 0 + C) = C =⇒C = 0. 所以 y = e−x sin x. 验算. 由y = e−x sin x 得 y′ = −e−x sin x + e−x cos x, 于是 y′ + y = −e−x sin x + e−x cos x  + e−x sin x = e−x cos x, 与原方程相符；又y(0) = e0 sin 0 = 0，初值条件也满足。"
      ],
      "answer": "e−x sin x",
      "pitfall": "一阶线性方程y′ + P(x)y = Q(x) 的通解公式\ny = e−\n´\nP(x) dx\nˆ\nQ(x)e\n´\nP(x) dx dx + C\n\n.\n当P(x) ≡a 为常数、Q(x) = e−axg(x) 时，积分因子eax 恰把指数抵消，方程直接化为\n(eaxy)′ = g(x)，这是本题这类「e−x· 三角函数」型右端的固定套路。\n易错\n（1）积分因子写成e−x（把P 的符号弄反），结果左端凑不成完全导数。记住：µ = e+\n´\nP ，是\n让(µy)′ = µ (y′ + Py) 成立的那一个。\n（2）套通解公式时把常数C 落在括号外，写成y = e−x sin x + C。C 必须留在积分因子的括\n号内，否则它不是齐次解的倍数。\n初值问题：通解之后怎么定常数\n真题里的填空题几乎全是初值问题：给方程，再给一个y(x0) = y0，让你写出那一条解。动\n作固定为两步：先求通解，再把初值代进去解出C。\nL24\n一阶微分方程\n定理/ 公式24.5 一阶线性初值问题的定积分写法\n若y(x0) = y0，可以直接写成\ny = e−\n´ x\nx0 P(t)dt\n\ny0 +\nˆ x\nx0\nQ(s) e\n´ s\nx0 P(t)dt ds\n\n,\n好处是常数自动定好，不必再解一个关于C 的方程。不习惯这个写法就照老路走：先求含C\n的通解，再代初值。\n真题演练（习题24.6）。下面这道2025 数三13 与上一节那道2011 数一10 是同一个动作，只\n是方程要先除以x 化成标准形。写完检查两件事：标准形有没有化对，初值代进去有没有把C 解\n对。",
      "difficulty": "★★★☆☆",
