      "analysis": "（I）一阶线性方程通解公式；（II）把「y 以T 为周期」翻译成一个数值条件y(T) = y(0)——\n靠的是「y(x + T) 与y(x) 满足同一方程」加上初值问题解的唯一性，于是存在唯一性化为一\n个关于初值C 的一元一次方程。",
      "solutionSteps": [
        "（I）f(x) = x 时求通解。方程为y′ + y = x，一阶线性，P(x) = 1，积分因子e ´ 1 dx = ex。两 边乘ex： (exy)′ = xex. 分部积分 ˆ xex dx = xex − ˆ ex dx = xex −ex + C, 故exy = xex −ex + C，即通解 y = x −1 + Ce−x (C 为任意常数). 验算：y′ = 1 −Ce−x，y′ + y = 1 −Ce−x + x −1 + Ce−x = x，成立。 （II）证明：当f 以T 为周期（T > 0）时，方程存在唯一的以T 为周期的解。",
        "第一步：写出全部解。仍用积分因子ex，(exy)′ = exf(x)。从0 到x 积分： exy(x) −y(0) = ˆ x etf(t) dt, L24 一阶微分方程 即以C = y(0) 为参数，方程的全部解为 y(x) = e−x  C + ˆ x etf(t) dt  , C ∈R. (∗) f 在R 上连续，故(∗) 对一切x ∈R 有定义，且不同的C 给出不同的解（它们在x = 0 处 的值就是C）。因此解与初值C 一一对应。",
        "第二步：把「周期为T」化成y(T) = y(0)。设y 是方程的解，令 φ(x) = y(x + T). 则φ′(x) = y′(x + T) = f(x + T) −y(x + T) = f(x) −φ(x)（这里用了f(x + T) = f(x)），即 φ 也满足同一个方程φ′ + φ = f。 充分性：若y(T) = y(0)，则φ(0) = y(T) = y(0)，即φ 与y 是同一初值问题 {u′ + u = f, u(0) = y(0)} 的解。由(∗) 知该初值问题的解唯一，故φ ≡y，也就是y(x+T) = y(x) 对一切x 成立，y 以T 为周期。 必要性：若y 以T 为周期，取x = 0 即得y(T) = y(0)。 所以 y 以T 为周期⇐⇒y(T) = y(0).",
        "第三步：解出唯一的C。在(∗) 中取x = T： y(T) = e−T  C + ˆ T etf(t) dt  , 而y(0) = C。令二者相等： e−T C + e−T ˆ T etf(t) dt = C =⇒C 1 −e−T  = e−T ˆ T etf(t) dt. 因T > 0，有e−T < 1，即1 −e−T ̸= 0，故上述关于C 的一次方程有且仅有一个解 C = e−T 1 −e−T ˆ T etf(t) dt = eT −1 ˆ T etf(t) dt. 由第一步的一一对应与第二步的等价刻画：满足y(T) = y(0) 的解恰有一个，即方程存在唯 一的以T 为周期的解，且它就是 y(x) = e−x  eT −1 ˆ T etf(t) dt + ˆ x etf(t) dt  . 证毕。 （II）的检验（以（I）为例的特例说明）. 若取f(x) = sin x（周期T = 2π），上式给出 ´ 2π et sin t dt = et 2 (sin t −cos t) 2π = 1 −e2π ，故C = e2π −1 · 1 −e2π = −1 2，对应的解 y = sin x −cos x （把C = −1 2 代入(∗) 并整理即得），它确实以2π 为周期，且y′ + y = cos x + sin x + sin x −cos x = sin x，与f 相符。 L24 一阶微分方程"
      ],
      "answer": "详见具体步骤解析",
      "pitfall": "按卷分配精力：三卷都不能省这一讲。17 年里数二平均每年从本讲拿走4.5 分、数一3.2 分、\n数三2.7 分，且数二数三的分主要以整道解答题的形式出现（11 个解答题位里数二占5 个、\n数三占3 个）。数三还要额外注意“包装题”那一类，3 道包装题里2 道在数三卷上，再加上\nL24\n一阶微分方程\nL27 那两道弹性题，数三从“认包装”这件事上能多拿一整道大题。数一的题位偏向填空与结\n构性证明（2018 数一18 这种），练习重点放在通解公式的熟练度和解的结构，不必追求偏难\n方程。\n本讲真题作业（做完这些，本讲就通了）\n读法：一格＝一道题。\n2016 ・数一・(15)\n=\n2016 ・数三・(15)\n同一题\n这样被红框框住的，是同一道题在几\n卷里同时考过，只做一次；框外单独一个徽章的，就是单卷题。\n一阶方程：可分离、齐次、线性、伯努利（19 题，正文已讲11 题，其中2 道跨卷重复）\n24.7\n2014 ・数二・(16)\n24.8\n2019 ・数一・(15)\n24.9\n2019 ・数二・(17)\n=\n2019 ・数三・(17)\n同一题\n24.10\n2021 ・数二・(20)\n24.12\n2022 ・数二・(18)\n24.14\n2018 ・数二・(16)\n24.15\n2018 ・数三・(12)\n24.16\n2010 ・数二・(2)\n=\n2010 ・数三・(2)\n同一题\n本讲名下真题共19 道，正文讲透11 道，其余8 道按上表自行完成——其中2 道是红框里的跨卷重复题，两卷\n（或三卷）同一道，做一次就够；题面与详解见《考研数学真题分类精解》。\n做题提示：正文已经把两类基本解法、两条变通、反问题各带过一道，作业只剩“解方程+ 接任务”这一大类和\n两道包装题，恰好是本讲最值钱的部分。按习题集顺序走：先做习题24.7（解方程求极值）、24.8（解方程并求拐\n点）、24.9（求旋转体体积）、24.10（法线截距最小）、24.12（求曲线弧长）这五道解答题，第一步都是正文2022\n数一17 那个动作，第二问分别接第1 编的不同工具；再做习题24.14（卷积型积分方程，与正文那道2016 数三\n18 是同一个动作），数三同学务必加做习题24.15（用微分近似做包装）；最后花二十秒做掉习题24.16 那道解的\n结构选择题，答案就是解λ + µ = 1 与λ −µ = 0。至于2010 数三11 与2016 数三16 这两道弹性题，方程就\n是本讲的可分离型，但它们记在L27，到那一讲一起做。\nL24\n一阶微分方程\n418",
