      "questionNumber": "(16)",
      "content": "设函数f(x) 在定义域I 上的导数大于零. 若对任意的x0 ∈I，曲线y = f(x) 在点(x0, f(x0))\n处的切线与直线x = x0 及x 轴所围成区域的面积恒为4，且f(0) = 2，求f(x) 的表达式.",
      "analysis": "「切线+ 竖直线x = x0 + x 轴」围出的一定是直角三角形：两条直角边分别是|f(x0)| 和次\n切距\nf(x0)\nf′(x0)\n。面积恒等于4 立刻给出可分离变量的微分方程。",
      "solutionSteps": [
        "第一步：把面积条件翻译成微分方程． 任取x0 ∈I，记y0 = f(x0)，y′ 0 = f′(x0) > 0。曲线在(x0, y0) 处的切线为 Y = y0 + f′(x0) (X −x0) . 令Y = 0 得它与x 轴的交点（因f′(x0) > 0 ̸= 0，交点唯一存在）： X = x0 − y0 f′(x0), 记为A =  x0 − y0 f′(x0), 0  . 另外，直线x = x0 与x 轴交于B = (x0, 0)，与切线交于切点M = (x0, y0)。 三条直线  切线，x = x0，x 轴 两两相交于A, B, M，围成△ABM，它在B 处是直角， 两条直角边为 |BM| = |y0| , |AB| = |x0 −X| = y0 f′(x0) = |y0| f′(x0). 于是 S = 1 2|AB| · |BM| = y2 2f′(x0) = 4. L27 微分方程应用题 x0 ∈I 是任取的，把下标去掉即得在I 上恒成立的微分方程 y2 2y′ = 4, 即 y2 = 8y′. （顺带看出y 在I 上处处非零：若某点y = 0，则该点面积为0 ̸= 4。又y 连续、f(0) = 2 > 0， 故y > 0 恒成立。）",
        "第二步：解可分离变量方程． 由y′ = y2 8 且y > 0，分离变量： dy y2 = dx =⇒ ˆ y−2 dy = ˆ 1 8 dx =⇒−1 y = x 8 + C.",
        "第三步：定常数．由f(0) = 2： −1 2 = 0 + C =⇒C = −1",
        "2. 故 −1 y = x 8 −1 2 = x −4 =⇒y = 4 −x. 因分母不能为零且需y > 0，又0 ∈I，故定义域取x < 4： f(x) = 4 −x, x ∈(−∞, 4). 验算．f(0) = 8 4 = 2 ✓；f′(x) = (4 −x)2 > 0 ✓（导数确实大于零）； f2(x) 2f′(x) = (4 −x)2 2 · (4 −x)2 = 64 16 = 4 ✓ 对一切x < 4 成立，与「面积恒为4」完全吻合。"
      ],
      "answer": "详见具体步骤解析",
      "pitfall": "曲线y = f(x) 在点(x, y) 处（y′ ̸= 0）：\n• 次切距（切线与x 轴交点到(x, 0) 的距离）=\ny\ny′\n；\n• 切线、竖直线x = x0、x 轴围成的直角三角形面积=\ny2\n2|y′|；\n• 法线、竖直线x = x0、x 轴围成的直角三角形面积= y2|y′|\n（次法距为|yy′|）。\n把这三条记熟，这类「几何量恒为常数」的题就直接落到一阶方程上。\nL27\n微分方程应用题\n易错\n（1）把围成的图形想成曲边梯形，去算\nˆ\nf。题目围区域的三条边全是直线（切线、x = x0、\nx 轴），是三角形，用1\n2· 底· 高即可。\n（2）漏掉1\n2，写成y2\ny′ = 4，得y =\n2 −x，代回面积得2 而非4。养成回代验算面积的习惯。\n（3）分离变量时把\nˆ\ny−2 dy 错写成ln y2 之类。正确是\nˆ\ny−2 dy = −y−1 + C。\n（4）不交代定义域。y =\n4 −x 在x = 4 处断裂，而I 是含0 的区间，故I ⊂(−∞, 4)；写答\n案时注明这一点更完整。\n进阶（习题27.4，4 星）。\n建模四步：设未知函数→把文字翻译成含导数的等式→求解→用初始条件定常数。\n这道把变限积分面积与三角形面积的比值作为条件，第2 步翻译出来不是微分方程而是含\n´ x\n0 f\n的积分等式。怎么从目标反推：你要的是f 满足的微分方程，所以先按L24 的老规矩取x = 0 把\n初值拿到手（求导之后这个信息就没了），再两边求导：",
      "difficulty": "★★★☆☆",
      "verified": true,
      "source": "Maki大串讲 真题27.2"
