      "source": "2022年·数二·第18题",
      "content": "设函数 $y(x)$ 是微分方程 $2xy'-4y=2\\ln x-1$ 的满足条件 $y(1)=\\frac14$ 的解，求曲线 $y=y(x)\\ (1\\le x\\le e)$ 的弧长。",
