        "（2）由第（1）问，\n$$\nf''(u)-f(u)=Cu.\n$$\n其通解为\n$$\nf(u)=A e^u+B e^{-u}-Cu.\n$$\n代入\n$$\nf(1)=1,\\qquad f'(1)=-1,\\qquad f''(1)=0,\n$$\n得到\n$$\n\\begin{cases}\nAe+Be^{-1}-C=1,\\\\\nAe-Be^{-1}-C=-1,\\\\\nAe+Be^{-1}=0.\n\\end{cases}\n$$\n由第三式与第一式得 $C=-1$。再将 $C=-1$ 代入前两式，解得\n$$\nAe=-1,\\qquad Be^{-1}=1,\n$$\n即\n$$\nA=-e^{-1},\\qquad B=e.\n$$\n因此\n$$\n\\boxed{f(u)=u-e^{u-1}+e^{1-u}}.\n$$"
