      "questionNumber": "(17)",
      "content": "已知函数y(x) 由方程x3 + y3 −3x + 3y −2 = 0 确定，求y(x) 的极值.",
      "analysis": "隐函数求极值：不必（也无法）解出y(x)，对方程两边求导得到y′ 的表达式，令y′ = 0 定\n驻点，把驻点横坐标回代原方程求出纵坐标，最后判别。",
      "solutionSteps": [
        "第一步：先确认y(x) 处处存在且可导．记F(x, y) = x3 + y3 −3x + 3y −2。它是多项式，处 处有连续偏导数，且 F ′ y = 3y2 + 3 ≥3 > 0. 于是对每个固定的x，F(x, ·) 关于y 严格单调增加，又y →±∞时F →±∞，由连续函数 的介值性，恰有一个y 使F(x, y) = 0。所以方程在整个(−∞, +∞) 上唯一确定了单值函数 y = y(x)；再由隐函数存在定理（F 有连续偏导且F ′ y ̸= 0），y(x) 处处可导。这一步是下面 「对方程两边求导」的合法性依据。",
        "第二步：求y′．两边对x 求导，把y 看作x 的函数（y3 按复合函数求导得3y2y′）： 3x2 + 3y2y′ −3 + 3y′ = 0. 两边除以3 并整理： x2 −1 + y2 + 1  y′ = 0 =⇒ y′ = 1 −x2 1 + y2 . （这里又用到1 + y2 ̸= 0，即上一步的F ′ y ̸= 0。）",
        "第三步：求驻点．分母1 + y2 > 0 恒成立，故 y′ = 0 ⇐⇒1 −x2 = 0 ⇐⇒x = ±1. 驻点的纵坐标必须回代原方程求： 把x = 1 代入x3 + y3 −3x + 3y −2 = 0： 1 + y3 −3 + 3y −2 = 0 =⇒y3 + 3y −4 = 0 =⇒(y −1) y2 + y + 4  = 0. 二次因式的判别式∆= 1 −16 = −15 < 0，无实根，故y = 1，即y(1) = 1。 把x = −1 代入： −1 + y3 + 3 + 3y −2 = 0 =⇒y3 + 3y = 0 =⇒y y2 + 3  = 0, 同理y2 + 3 > 0，故y = 0，即y(−1) = 0。",
        "第四步：判别（法一，一阶导变号）．由y′ = 1 −x2 1 + y2 ，分母恒正，y′ 的符号完全由分子1 −x2 决定： x (−∞, −1) −1 (−1, 1) (1, +∞) y′ − + − y 减 极小 增 极大 减 故x = −1 是极小值点，x = 1 是极大值点。",
        "第四步（法二，二阶导判别）．把第二步整理成 1 + y2 y′ = 1 −x2，两边再对x 求导： 2y y′2 + 1 + y2 y′′ = −2x. 在x = 1 处（此时y = 1，y′ = 0）：0 + (1 + 1)y′′ = −2，得y′′(1) = −1 < 0，极大值点； 在x = −1 处（此时y = 0，y′ = 0）：0 + (1 + 0)y′′ = 2，得y′′(−1) = 2 > 0，极小值点。两 法结论一致。"
      ],
