      "questionNumber": "(17)",
      "content": "已知函数z = z(x, y) 由方程\nx2 + y2\nz + ln z + 2(x + y + 1) = 0 确定，求z = z(x, y) 的极\n值.",
      "analysis": "隐函数的极值：驻点条件∂z\n∂x = ∂z\n∂y = 0 不必先解出zx, zy 的表达式，直接把它代回“对方程\n两边求导”所得的式子即可；二阶导也在zx = zy = 0 的前提下再求一次导。",
      "solutionSteps": [
        "记方程为 F(x, y, z) = x2 + y2 z + ln z + 2(x + y + 1) = 0. 由于出现ln z，必有z > 0；又F ′ z = x2 + y2 + 1 z > 0，故由隐函数存在定理，方程确实在每 一点附近唯一确定可微函数z = z(x, y)。",
        "第一步：对方程两边分别关于x, y 求偏导（z 视为x, y 的函数）． 2xz + x2 + y2 ∂z ∂x + 1 z ∂z ∂x + 2 = 0,",
        "(1) 2yz + x2 + y2 ∂z ∂y + 1 z ∂z ∂y + 2 = 0.",
        "(2)",
        "第二步：求驻点．令∂z ∂x = ∂z ∂y = 0，(1)(2) 立即化为 2xz + 2 = 0, 2yz + 2 = 0 =⇒xz = yz = −1. 因z > 0，得 x = y = −1 z . 把它代回原方程：  1 z2 + 1 z2  z + ln z + 2  −1 z −1 z + 1  = 2 z + ln z −4 z + 2 = ln z −2 z + 2 = 0. 令g(z) = ln z −2 z + 2 (z > 0)。观察到g(1) = 0 −2 + 2 = 0，故z = 1 是一个根；又 g′(z) = 1 z + 2 z2 > 0 (z > 0), g 在(0, +∞) 上严格单调增，所以z = 1 是唯一的根。相应地x = y = −1 1 = −1。 于是唯一的驻点是(x, y) = (−1, −1)，对应z = 1。（代入原方程核对：(1 + 1) · 1 + ln 1 + 2(−1 −1 + 1) = 2 + 0 −2 = 0 ✓）"
      ],
