      "content": "求函数 $f(x,y)=(2x^2-y^2)e^x$ 的极值。",
      "answer": "极大值为 $\\dfrac{8}{e^2}$，在 $(-2,0)$ 处取得；无极小值。",
      "analysis": "考查知识点：数一 / 2026。",
      "solutionSteps": [
        "设\n$$\nf(x,y)=(2x^2-y^2)e^x.\n$$\n先求一阶偏导数：\n$$\nf_x=e^x(2x^2+4x-y^2),\\;\nf_y=-2ye^x.\n$$\n由 $f_x=f_y=0$，且 $e^x>0$，得\n$$\ny=0,\\; 2x(x+2)=0.\n$$\n所以驻点只有\n$$\n(0,0),\\; (-2,0).\n$$",
        "再求二阶偏导数：\n$$\nf_{xx}=e^x(2x^2+8x+4-y^2),\\;\nf_{xy}=-2ye^x,\\;\nf_{yy}=-2e^x.\n$$",
        "在 $(0,0)$ 处，\n$$\nf_{xx}=4,\\; f_{xy}=0,\\; f_{yy}=-2,\n$$\n故\n$$\nf_{xx}f_{yy}-f_{xy}^2=-8<0.\n$$\n因此 $(0,0)$ 是鞍点。",
        "在 $(-2,0)$ 处，\n$$\nf_{xx}=-4e^{-2}<0,\\;\nf_{xy}=0,\\;\nf_{yy}=-2e^{-2}<0,\n$$\n相应的二次型负定，因此 $(-2,0)$ 是极大值点，极大值为\n$$\nf(-2,0)=8e^{-2}=\\frac8{e^2}.\n$$",
        "函数在整个平面上可微，局部极值点只能是驻点；上述两个驻点中，一个是鞍点，另一个是极大值点，所以不存在极小值点。此外，\n$$\nf(0,y)=-y^2\\to-\\infty\\; (|y|\\to\\infty),\n$$\n故也不存在最小值。",
        "综上，极大值为\n$$\n\\boxed{\\frac8{e^2}},\n$$\n无极小值。"
      ],
