        "令\n$$\nx=r\\cos\\theta,\\qquad y=r\\sin\\theta.\n$$\n对 $D_1$，\n$$\n0\\le\\theta\\le\\frac\\pi2,\\qquad 0\\le r\\le2.\n$$\n对 $D_2$，直线 $y=x+2$ 化为\n$$\nr(\\sin\\theta-\\cos\\theta)=2,\n$$\n所以\n$$\n\\frac\\pi2\\le\\theta\\le\\pi,\\qquad\n0\\le r\\le\\frac2{\\sin\\theta-\\cos\\theta}.\n$$",
        "第三步：计算第一部分积分。",
        "极坐标下，\n$$\n\\frac{(x-y)^2}{x^2+y^2}\n=(\\cos\\theta-\\sin\\theta)^2,\n$$\n且 $\\mathrm dx\\,\\mathrm dy=r\\,\\mathrm dr\\,\\mathrm d\\theta$。因此\n$$\n\\begin{aligned}\nI_1\n&=\\int_0^{\\pi/2}(\\cos\\theta-\\sin\\theta)^2\n\\left(\\int_0^2r\\,\\mathrm dr\\right)\\mathrm d\\theta\\\\\n&=2\\int_0^{\\pi/2}(1-\\sin2\\theta)\\,\\mathrm d\\theta\\\\\n&=2\\left[\\theta+\\frac12\\cos2\\theta\\right]_0^{\\pi/2}\\\\\n&=\\pi-2.\n\\end{aligned}\n$$",
        "第四步：计算第二部分积分并相加。",
