      "analysis": "这道题排在二重积分这一讲，是因为第(II) 问的形心要用二重积分定义；第(I) 问的弧长在\n第21 讲就做得完，那里放了一个「引」。弧长题的关键是让1 + y′2 配成完全平方好开方——\n形如y′ = x\n2 −1\n2x 的函数正是为此设计的；第(II) 问是形心公式¯x =\n˜\nD x dσ\n˜\nD dσ\n在曲边梯形\n上的一维化。",
