      "source": "2023年·数三·第19题",
      "content": "已知平面区域\n$$\nD=\\{(x,y):(x-1)^2+y^2\\le1\\}.\n$$\n计算下列含绝对值的二重积分：\n$$\nI=\\iint_D\\left|\\sqrt{x^2+y^2}-1\\right|\n\\,\\mathrm dx\\,\\mathrm dy.\n$$",
      "answer": "$$\n3\\sqrt3-\\frac{\\pi+32}{9}.\n$$",
      "analysis": "考查知识点：数三 / 2023。 被积函数中的绝对值作用于整个差 $\\sqrt{x^2+y^2}-1$。转为极坐标后，应按 $|r-1|$ 分段计算。",
      "solutionSteps": [
        "第一步：确定极坐标积分区域。",
        "令 $x=r\\cos\\theta$、$y=r\\sin\\theta$。由\n$$\n(x-1)^2+y^2\\le1\n$$\n得\n$$\nr^2\\le2r\\cos\\theta.\n$$\n所以区域可表示为\n$$\n-\\frac\\pi2\\le\\theta\\le\\frac\\pi2,\n\\qquad 0\\le r\\le2\\cos\\theta.\n$$",
        "利用关于 $x$ 轴的对称性，原积分为\n$$\nI=2\\int_0^{\\pi/2}\n\\left[\\int_0^{2\\cos\\theta}r|r-1|\\,\\mathrm dr\\right]\n\\mathrm d\\theta.\n$$\n其中因子 $r$ 来自极坐标面积元。",
        "第二步：在 $r=1$ 处去掉绝对值。",
        "记\n$$\nH(\\theta)=\\int_0^{2\\cos\\theta}r|r-1|\\,\\mathrm dr.\n$$",
        "当 $0\\le\\theta\\le\\pi/3$ 时，$2\\cos\\theta\\ge1$，故\n$$\n\\begin{aligned}\nH(\\theta)\n&=\\int_0^1r(1-r)\\,\\mathrm dr\\\\\n&\\quad+\\int_1^{2\\cos\\theta}r(r-1)\\,\\mathrm dr\\\\\n&=\\frac83\\cos^3\\theta-2\\cos^2\\theta+\\frac13.\n\\end{aligned}\n$$",
        "当 $\\pi/3\\le\\theta\\le\\pi/2$ 时，$2\\cos\\theta\\le1$，故\n$$\n\\begin{aligned}\nH(\\theta)\n&=\\int_0^{2\\cos\\theta}r(1-r)\\,\\mathrm dr\\\\\n&=2\\cos^2\\theta-\\frac83\\cos^3\\theta.\n\\end{aligned}\n$$",
        "第三步：计算角度积分。",
        "令\n$$\nB(\\theta)=\\frac83\\cos^3\\theta-2\\cos^2\\theta.\n$$\n它的一个原函数为\n$$\n\\begin{aligned}\nF(\\theta)\n&=\\frac83\\sin\\theta-\\frac89\\sin^3\\theta\\\\\n&\\quad-\\theta-\\frac12\\sin2\\theta.\n\\end{aligned}\n$$\n因此\n$$\n\\begin{aligned}\nI&=2\\int_0^{\\pi/3}\n\\left[B(\\theta)+\\frac13\\right]\\mathrm d\\theta\\\\\n&\\quad-2\\int_{\\pi/3}^{\\pi/2}B(\\theta)\\,\\mathrm d\\theta\\\\\n&=4F\\left(\\frac\\pi3\\right)\n-2F\\left(\\frac\\pi2\\right)+\\frac{2\\pi}{9}.\n\\end{aligned}\n$$",
        "由\n$$\nF(0)=0,\n$$\n$$\nF\\left(\\frac\\pi3\\right)=\\frac{3\\sqrt3}{4}-\\frac\\pi3,\n$$\n$$\nF\\left(\\frac\\pi2\\right)=\\frac{16}{9}-\\frac\\pi2,\n$$\n得到\n$$\n\\boxed{I=3\\sqrt3-\\frac{\\pi+32}{9}}.\n$$"
      ],
      "pitfall": "注意审题条件与运算符号，规避常见计算失误。",
