        "第3步：而D 关于y 轴对称、x 是关于x 的奇函数，所以\n¨\nD\nx dx dy = 0 =⇒\n˛\nL+BA\n= 0.\n再算补上的那段：在BA 上y ≡0，dy = 0，故\nˆ\nBA\nxy dx + x2 dy =\nˆ −1\nx · 0 dx + 0 = 0.\n仅一\n所以\nˆ\nL\n=\n˛\nL+BA\n−\nˆ\nBA\n= 0 −0 = 0,\n与解法一一致。"
