      "answer": "0",
      "pitfall": "格林三查——每一道格林题动笔之前，照下面三行写一遍，一行都不许省。\n1. ➀曲线闭不闭？闭⇒直接用。不闭⇒先补线：添一段最简单的线段（平行坐标轴，或直\n接连两个端点）把它凑成闭回路，记账式写死：\nˆ\nL\n=\n˛\nL+L0\n−\nˆ\nL0\n。\n2. ➁方向是不是正向？正向的判据是“沿着走时D 在左边”，外边界就是逆时针。给的是顺\n时针⇒先加一个负号再套公式。补线时补的那一段也要凑成正向。\n仅一\n3. ➂区域内有没有奇点？看P, Q 的分母。分母形如x2 + y2、4x2 + y2、x2 + 4y2 而闭曲线\n围住了原点⇒有奇点，格林的前提不成立，必须挖洞（见后面一节）。分母不为零、P, Q\n处处有连续偏导⇒无奇点，放心用。\n三查之外还有一个先手动作：先把Qx −Py 算出来看看。它若是常数（尤其是0 或1），二重\n积分立刻退化成“常数× 面积”，整题几乎白送。\n真题演练（入门形态，习题35.6）。先看最干净的一道。格林三查：➀曲线是抛物线弧，从(1, 0)\n到(−1, 0)，不闭→补x 轴上从(−1, 0) 到(1, 0) 的线段；➁补完之后回路恰好是逆时针，正向，\n不用加负号；➂P = y + cos x、Q = 2x + cos y 处处有连续偏导，没有奇点，不必挖洞。三查过\n关，再算先手：Qx −Py = 2 −1 = 1，二重积分就是面积。",
