      "pitfall": "挖洞是格林三查第➂条不过关时的标准处置。动作固定成三步：\n1. 在奇点周围挖一条小闭曲线Lε，取顺时针（这样它与外面的L 一起构成环形区域的正向\n边界，环形区域里没有奇点，格林公式在那上面成立）。\n2. 在环形区域上用格林：\n˛\nL\n+\n˛\nLε\n=\n¨\n环形\n(Qx −Py)。真题里这个二重积分通常是0（因为\nQx −Py ≡0），于是\n˛\nL\n= −\n˛\nLε\n=\n˛\nL−\nε\n——原积分等于沿小曲线逆时针的积分，与L 长\n什么样无关。\n3. 在小曲线上算：因为小曲线是特意挑的，分母变成常数，积分几行就完。\n那条小曲线的形状由分母决定，不是随便取圆。分母是4x2 + y2 就挖椭圆4x2 + y2 = ε2，分\n母是x2 + y2 才挖圆。这一条每年都有人栽。\n真题演练（习题35.10）。格林三查：➀L 是圆x2 + y2 = 2，闭合，不用补线；➁题目给的是逆\n仅一\n时针，正向，不加负号；➂分母4x2 + y2 在原点为零，而L 把原点围在里面——有奇点，必须挖\n洞。挖的是椭圆4x2 + y2 = ε2 而不是圆，目的就是让分母变成常数ε2：",
