      "analysis": "bn = 2\nˆ 1\nf(x) sin nπx dx 正是f 在[0, 1] 上的正弦系数，所以S(x) 是f 的奇延拓（周期2）\n的傅里叶级数之和。用「奇性+ 周期性」把−9\n4 搬回(0, 1)，再用狄利克雷定理取值。",
      "solutionSteps": [
        "第一步：认清S(x) 是谁的和函数．在[0, l] 上作正弦级数展开时，系数公式是bn = l ˆ l f(x) sin nπx l dx。本题l = 1，公式恰为题给的bn = 2 ˆ 1 f(x) sin nπx dx。因此 ∞ X n=1 bn sin nπx 就是把f(x) = x −1 先奇延拓到[−1, 1]、再以2 为周期延拓到整个R 所得 函数F(x) 的傅里叶级数。记这个和函数为S(x)，则S 具有两条性质： S(−x) = −S(x) (奇), S(x + 2) = S(x) (周期2). （这两条不必验算：正弦函数族{sin nπx} 每一个都是奇的、以2 为周期，其线性组合的极限 自然继承。）",
        "第二步：把−9 4 化到(0, 1) 内．先用周期性（加上4 = 2 × 2 个周期）： S  −9  = S  −9 4 + 4  = S 7  . 再用一次周期性与奇性把它挪到(0, 1)： S 7  = S 7 4 −2  = S  −1  = −S 1  .",
        "第三步：用狄利克雷收敛定理取值．延拓后的F 在(0, 1) 上就等于f，f 在x = 1 4 处连续 （ x −1 处处连续，只是在x = 1 2 不可导，而可导性与收敛定理无关）。F 在一个周期内分段 单调、只有有限个第一类间断点（间断点在x = 0, ±1, ±2, · · · 处，因为f(0) = f(1) = 1 2 ̸= 0）， 满足狄利克雷条件。故在连续点x = 1 4 处 S 1  = f 1  = 4 −1 = 1",
        "4. 于是 S  −9  = −S 1  = −1",
        "4. 仅一 为什么不是其他选项．(B) 1 4 是只用周期性、漏掉奇性负号的结果：把−9 4 加4 变成7 4 后， 若忘记7 4 落在「负半段的镜像」上，就会误取+f  1  = 1 4。(A) 3 4 与(D) −3 4 更是无须细 算即可排除：f 在[0, 1] 上的值域是  0, 1  ，奇延拓后|F(x)| ≤1 2，故和函数S 的取值必在  −1 2, 1  内（间断点取平均值也不会超出），绝不可能等于±3 4。故选(C)。 数值验证．直接算出bn = πn  (−1)n+1 + 1  −4 sin nπ π2n2 ，取前2000 项求部分和得S −9  ≈ −0.24977，其算术平均（消除吉布斯振荡）为−0.24999，确为−1 4。"
      ],
      "answer": "C",
      "pitfall": "搬点这一步的唯一失分点是符号。建议固定写法：先只用周期性把x0 搬进[−l, l]，若落在负\n半边再用一次S(−x) = −S(x)，把负号单独提在最前面，最后统一乘回去。不要一边搬一边\n翻符号，两步混在一起最容易错。\n真题演练（同一条线，十二年后原样重放）。2025 数一12。和上题的结构一模一样，只有一处不\n同：搬完点之后落在了f 的分段点x = 1\n2 上——于是第3 步要取左右极限的平均，而不是把f( 1\n2)\n直接代进去：",
      "difficulty": "★★★☆☆",
