      "pitfall": "按卷分配精力：本讲是中等投入，别按重点讲的规格来，但内部侧重三卷不同。数二、数三：\n每年2.6 ／2.0 分，重心在初等变换（24 ／19 分，是三卷里数二数三明显占优的一块），矩\n阵方程各10.4 分是必须拿的大题分；秩只有9 ／5 分——性质背熟能判定即可，2023 数一5\n那种难度5.0 的题不必碰，但伴随秩三分法那两道（2024 数二9、2026 数三6）正好一卷一\n道，都要做。数一：每年2.1 分，是三卷最低，但结构完全反过来——初等变换只有8 分，而\n秩23 分是三卷最高，且难题（难度4–5）全部出在数一卷上——数一同学要把秩的不等式练\n到能随手举反例。三卷共同的动作：(A | B) →(E | X) 的增广消元，闭着眼睛也要写对。\n本讲真题作业（做完这些，本讲就通了）\n读法：一格＝一道题。\n2016 ・数一・(15)\n=\n2016 ・数三・(15)\n同一题\n这样被红框框住的，是同一道题在几\n卷里同时考过，只做一次；框外单独一个徽章的，就是单卷题。\n初等变换与初等矩阵（6 题，正文已讲2 题，其中2 道跨卷重复）\n45.2\n2020 ・数一・(5)\n45.3\n2021 ・数二・(10)\n=\n2021 ・数三・(7)\n同一题\n45.4\n2022 ・数二・(16)\n=\n2022 ・数三・(15)\n同一题\n45.6\n2025 ・数二・(9)\n矩阵的秩（8 题，正文已讲3 题）\n45.7\n2010 ・数一・(5)\n45.8\n2012 ・数一・(13)\n45.9\n2016 ・数二・(14)\nL45\n初等变换、初等矩阵与秩\n45.11\n2023 ・数一・(5)\n45.12\n2024 ・数二・(9)\n矩阵方程（2 题，正文已讲1 题）\n45.16\n2022 ・数一・(15)\n本讲名下真题共16 道，正文讲透6 道，其余10 道按上表自行完成——其中2 道是红框里的跨卷重复题，两卷\n（或三卷）同一道，做一次就够；题面与详解见《考研数学真题分类精解》。\n做题提示：本讲20 个选填题位才是主体，按考点成组做。初等矩阵那6 道（2020 数一5、2021 数二10、2022 数\n二16、2025 数二9 是正文之外剩下的四道）连着做完，数二数三同学优先。秩那8 道数一同学必须做完：2010\n数一5、2012 数一13、2016 数二14 是基础形态（2012 数一13 正文已给过思路，动笔补完），2023 数一5 是\n难度5.0 的硬骨头、留到冲刺期，2025 数一7 与正文那道2021 数一7 是“分块+ 秩”的一对，做完前者再回\n头把正文那道补完；2024 数二9 与2026 数三6 是伴随秩三分法的一对，一样配着做。2022 数一15 是矩阵方\n程的填空版（因式分解求逆），顺手做掉；正文那道2015 年的大题务必动笔重写一遍。两道“搬家”的题别在这\n里找：r(A, AB) = r(A) 那道2018 三卷同题与AC −CA = B 那道2013 三卷同题现在都在L48。\nL45\n初等变换、初等矩阵与秩\n762",
