      "content": "已知 $A$ 是 $m\\times n$ 矩阵，$\\beta$ 是 $m$ 维非零向量。若 $A$ 有 $k$ 阶非零子式，则（ ）。",
      "answer": "A",
      "analysis": "考查知识点：数三 / 2025。",
      "solutionSteps": [
        "标准解法：若 $A$ 有 $m$ 阶非零子式，则 $r(A)=m$，即 $A$ 的列空间等于 $\\mathbb R^m$，所以对任意 $m$ 维向量 $\\beta$，方程 $Ax=\\beta$ 都有解，A 正确。若仅知存在 $k\\lt m$ 阶非零子式，只能推出 $r(A)\\ge k$，无法判断给定 $\\beta$ 是否属于列空间。检验：$k=m$ 就是满行秩条件。"
      ],
