      "content": "设A =\n\n\n\n\n−2\n−4\n1\n−1\n1\n0\n−3\n\n\n\n，E 为3 阶单位矩阵.\n(I) 求方程组Ax = 0 的一个基础解系；\n(II) 求满足AB = E 的所有矩阵B.",
