      "answer": "详见具体步骤解析",
      "pitfall": "（1）矩阵方程AX = C 等价于把C 按列拆成若干个非齐次方程组Ax = ci；它们系数矩阵\n相同，可对[A ... C] 一次性作行变换同时解出。\n（2）A 为m × n 矩阵时，AB = Em 有解⇐⇒r(A) = m（行满秩）；此时B 称为A 的右\n逆，当m < n 时右逆有无穷多个，其自由度就是Ax = 0 的基础解系维数。\n易错\n（1）忘了B 应是4 × 3 而不是3 × 3——A 不是方阵，不能套「B = A−1」。\n（2）只写出三个特解拼成的那一个B。因为Ax = 0 有非零解，B 有无穷多个，而且三列的\n参数k1, k2, k3 相互独立，不能只用一个k。\n真题演练（设元型，三卷同题）。下面这道2013 年的形态最特别：方程是AC −CA = B，C 在\n左也在右，提不出公因子。于是走路线二——把C 的四个元素设成未知数，整个矩阵方程变成一\n个四元线性方程组，第一问“a, b 取何值时存在C”问的正是这个方程组何时有解。",
