      "content": "设A =\na\n0\n!\n，B =\n1\nb\n!\n. 当a，b 为何值时，存在矩阵C 使得AC −CA = B，并\n求所有矩阵C.",
      "analysis": "含未知矩阵的方程AC −CA = B，C 被夹在中间无法整体移项，标准做法是把C 的四个\n元素设成未知量，逐元素比较，化为四元线性方程组讨论相容性。",
      "solutionSteps": [
        "第1步：设C =\nx1\nx2\nx3\nx4\n!\n，分别计算\nAC =\na\n0\n!\nx1\nx2\nx3\nx4\n!\n=\nx1 + ax3\nx2 + ax4\nx1\nx2\n!\n,\nCA =\nx1\nx2\nx3\nx4\n!\na\n0\n!\n=\nx1 + x2\nax1\nx3 + x4\nax3\n!\n.\n两式相减：\nAC −CA =\n\n\nax3 −x2\n−ax1 + x2 + ax4\nx1 −x3 −x4\nx2 −ax3\n\n.\n令其等于B =\n1\nb\n!\n，得关于x1, x2, x3, x4 的线性方程组\n(i)\n−x2 + ax3 = 0,\n(ii) −ax1 + x2 + ax4 = 1,\n(iii) x1 −x3 −x4 = 1,\n(iv) x2 −ax3 = b.\n定b．把(i) 与(iv) 相加，左边恰好抵消：0 = b。",
        "第2步：故b = 0 是方程有解的必要条件。",
        "第3步：定a．由(i) 得x2 = ax3，代入(ii)：\n−ax1 + ax3 + ax4 = 1,\n即\n−a (x1 −x3 −x4) = 1.\n而(iii) 说x1 −x3 −x4 = 1，代入即得−a = 1，故a = −1。",
        "第4步：反过来验证充分性并求出全部C．当a = −1, b = 0 时，方程组化为\nx2 = −x3,\nx1 −x3 −x4 = 1,\n（此时(ii) 变为x1 −x3 −x4 = 1，与(iii) 重合；(iv) 变为x2 + x3 = 0，与(i) 重合），故只有两\n个独立方程、四个未知量，自由未知量取x1 = k1，x3 = k2，则x2 = −k2，x4 = k1 −k2 −1。"
      ],
      "answer": "详见具体步骤解析",
      "pitfall": "“线性表出的反问题”为什么也在这里：L46 那条翻译“β 可由α1, . . . , αs 表出⇐⇒Ax = β\n有解”把向量组的问题变成了方程组的问题，而反问题要的不只是“有没有解”，还要真的把\n表示系数解出来——那一步就是L47 的消元。所以这类题（题面说“α 组不能由β 组表出，求\n参数；再反过来把β 用α 表出”）整类记在本节。\n这个考点17 年有9 个题位（4 选1 填4 解），平均难度3.4，排进全书121 个考点的难度榜\n前10。低频高难，性价比取决于你的目标分：冲130 以上必须练，保100 分可以最后再看。\n还有一句翻译放在这里备查：题干若说“x 与α1, . . . , αs 都正交”，那就是s 个方程αT\ni x = 0\n拼成的齐次方程组，解它用的还是L47 那套动作。正交本身的性质与它的配套算法在L51，本\n讲不展开。\n真题演练（线性表出的反问题，三卷同题）。“α 组不能由β 组表示”翻译成矩阵语言就是“方\n程组(β1, β2, β3)x = αi 中至少有一个无解”，于是必有|β1, β2, β3| = 0——这是第（I）问的全部\n依据。第（II）问反过来要真的把β 用α 表出，走( α | β ) →(E | X)，这正是上一节的拆列法。",
