      "content": "已知向量组 $\\alpha_1=\\begin{pmatrix}1\\\\0\\\\-1\\\\-1\\end{pmatrix}$，$\\alpha_2=\\begin{pmatrix}1\\\\-1\\\\0\\\\-2\\end{pmatrix}$，$\\alpha_3=\\begin{pmatrix}0\\\\-1\\\\1\\\\-1\\end{pmatrix}$，$\\alpha_4=\\begin{pmatrix}0\\\\1\\\\-1\\\\1\\end{pmatrix}$，记 $A=(\\alpha_1,\\alpha_2,\\alpha_3,\\alpha_4)$，$G=(\\alpha_1,\\alpha_2)$。（1）证明：$\\alpha_1,\\alpha_2$ 是 $\\alpha_1,\\alpha_2,\\alpha_3,\\alpha_4$ 的极大线性无关组；（2）求矩阵 $H$ 使得 $A=GH$，并求 $A^{10}$。",
