        "第一个方程组的增广矩阵为\n$$\n\\left[\\begin{array}{cc|c}\nA&B&0\\\\\nO&B&0\n\\end{array}\\right].\n$$\n将上面每一行减去下面的对应行，即依次作\n$$\nR_i\\leftarrow R_i-R_{n+i},\n\\qquad i=1,\\ldots,n,\n$$\n得到\n$$\n\\left[\\begin{array}{cc|c}\nA&O&0\\\\\nO&B&0\n\\end{array}\\right].\n$$\n这里每一步都是普通的初等行变换，因此不改变方程组的解。",
