      "source": "2024年·数三·第15题",
      "content": "设 $A$ 为 $3$ 阶矩阵，$A^*$ 为 $A$ 的伴随矩阵。若 $r(2E-A)=1$，$r(A+E)=2$，则 $|A^*|=\\underline{\\hspace{3em}}$。",
      "answer": "$16$",
      "analysis": "考查知识点：数三 / 2024。",
      "solutionSteps": [
        "由 $r(2E-A)=1$ 知 $2$ 是 $A$ 的特征值，且其几何重数为 $2$，故代数重数至少为 $2$。由 $r(A+E)=2$ 知 $-1$ 也是 $A$ 的特征值。三阶矩阵的三个特征值因而为 $2,2,-1$，所以 $|A|=-4$。又对三阶矩阵有 \n$$\n|A^*|=|A|^{3-1}=|A|^2=16.\n$$"
      ],
      "pitfall": "注意审题条件与运算符号，规避常见计算失误。",
