      "source": "2024年·数一·第21题",
      "content": "已知数列 $\\{x_n\\}$，$\\{y_n\\}$，$\\{z_n\\}$ 满足 $x_0=-1$，$y_0=0$，$z_0=2$，且 \n$$\n\\begin{cases}x_n=-2x_{n-1}+2z_{n-1},\\\\y_n=-2y_{n-1}-2z_{n-1},\\\\z_n=-6x_{n-1}-3y_{n-1}+3z_{n-1}.\n\\end{cases}\n$$\n 记 $\\alpha_n=\\begin{pmatrix}x_n\\\\y_n\\\\z_n\\end{pmatrix}$，写出满足 $\\alpha_n=A\\alpha_{n-1}$ 的矩阵 $A$，并求 $A^n$ 及 $x_n,y_n,z_n$（$n=1,2,\\cdots$）。",
      "answer": "$A=\\begin{pmatrix}-2&0&2\\\\0&-2&-2\\\\-6&-3&3\\end{pmatrix}$；令 $r=(-2)^n$，则 \n$$\nA^n=\\begin{pmatrix}-4-r&-2-r&2\\\\4+2r&2+2r&-2\\\\-6&-3&3\\end{pmatrix}\n$$\n，$x_n=8+(-2)^n$，$y_n=-8-2(-2)^n$，$z_n=12$。",
      "analysis": "考查知识点：数一 / 2024。 由递推关系可得\n$$\n\\alpha_n=A\\alpha_{n-1},\n\\qquad\nA=\n\\begin{pmatrix}\n-2&0&2\\\\\n0&-2&-2\\\\\n-6&-3&3\n\\end{pmatrix}.\n$$",
      "solutionSteps": [
        "先计算特征多项式：\n$$\n\\begin{aligned}\n|\\lambda E-A|\n&=\n\\begin{vmatrix}\n\\lambda+2&0&-2\\\\\n0&\\lambda+2&2\\\\\n6&3&\\lambda-3\n\\end{vmatrix}\\\\\n&=\\lambda(\\lambda-1)(\\lambda+2).\n\\end{aligned}\n$$\n因此 $A$ 的特征值为 $0,1,-2$。三个特征值互不相同，所以 $A$ 可对角化。",
        "当 $n\\geq1$ 时，设二次多项式\n$$\np_n(t)=c_1t+c_2t^2\n$$\n满足\n$$\np_n(0)=0,\\qquad p_n(1)=1,\\qquad p_n(-2)=(-2)^n.\n$$\n于是\n$$\n\\begin{cases}\nc_1+c_2=1,\\\\\n-2c_1+4c_2=(-2)^n,\n\\end{cases}\n$$\n解得\n$$\nc_1=\\frac{4-(-2)^n}{6},\n\\qquad\nc_2=\\frac{(-2)^n+2}{6}.\n$$\n由于 $p_n(t)$ 与 $t^n$ 在 $A$ 的三个特征值处取值相同，故\n$$\nA^n=p_n(A)\n=\\frac{4-(-2)^n}{6}A\n+\\frac{(-2)^n+2}{6}A^2.\n$$\n直接计算\n$$\nA^2=\n\\begin{pmatrix}\n-8&-6&2\\\\\n12&10&-2\\\\\n-6&-3&3\n\\end{pmatrix}.\n$$\n令 $r=(-2)^n$，代入并化简，得到\n$$\nA^n=\n\\begin{pmatrix}\n-4-r&-2-r&2\\\\\n4+2r&2+2r&-2\\\\\n-6&-3&3\n\\end{pmatrix}.\n$$",
        "又\n$$\n\\alpha_0=\n\\begin{pmatrix}\n-1\\\\\n0\\\\\n2\n\\end{pmatrix},\n\\qquad\n\\alpha_n=A^n\\alpha_0,\n$$\n所以\n$$\n\\begin{pmatrix}\nx_n\\\\\ny_n\\\\\nz_n\n\\end{pmatrix}\n=\n\\begin{pmatrix}\n8+r\\\\\n-8-2r\\\\\n12\n\\end{pmatrix}.\n$$\n即\n$$\nx_n=8+(-2)^n,\\qquad\ny_n=-8-2(-2)^n,\\qquad\nz_n=12.\n$$"
      ],
      "pitfall": "注意审题条件与运算符号，规避常见计算失误。",
      "verified": true
