        "但该条件并不充分。例如取\n$$\nA=\n\\begin{pmatrix}\n0&1&0\\\\\n0&0&0\\\\\n0&0&0\n\\end{pmatrix}.\n$$\n矩阵 $A$ 是非零幂零矩阵，且 $A^2=O$，故 $A$ 不可对角化；然而\n$$\nA^3-A^2=O,\n$$\n零矩阵可以对角化。",
        "因此“$A^3-A^2$ 可对角化”是“$A$ 可对角化”的必要但不充分条件，选 B。"
