      "pitfall": "这类题的两秒解法：实对称⇒相似于Λ，而r(A) = 非零特征值的个数、tr A = 特征值之和。\n两个数字一卡，对角元就唯一定死了。注意“r(A) = 非零特征值个数”这条只对可对角化的\n矩阵成立，一般矩阵不能这么用——这正是选择题埋的坑。\n真题演练（含参数版，三卷同题）。同一条路的加难形态：2013 年三卷同题给一个含a, b 的实对\n称矩阵，问它与某个对角阵相似的充分必要条件。关键仍是性质3——左边实对称必可对角化，右\n边本来就是对角阵，于是“相似”直接退化成“特征值（含重数）相同”，充分必要性一步到位。",
