        "第3步：直接计算\n|2E −M| =\n−a\n−1\n−a\n2 −b\n−a\n−1\n−a\nr3+r1\n=\n−a\n−1\n−a\n2 −b\n−a\n−2a\n= 2a\n−1\n−a\n−a\n= 2a · (−2a) = −4a2,\n（第3 行只剩−2a 一个非零元，沿它展开，代数余子式符号为(−1)3+2 = −1。",
        "第4步：）令−4a2 = 0\n即得a = 0；再由第三步知a = 0 时对一切b 都相似，故充要条件是「a = 0，b 任意」，与前\n面结论一致。"
