      "answer": "B",
      "pitfall": "两个最高频失分点：\n• 对不同特征值的向量也去做施密特——白费时间，且会破坏特征向量的身份。\n• 忘记单位化，写出的Q 不是正交矩阵，后面QT AQ 全错。\n第三个常被忽略的：Q 的列序必须与Λ 的对角元序一致，而且题目若指定了Q 的某一列（真\n题里出现过），就必须把对应的特征值放在Λ 的第一位。\nL51\n实对称矩阵\n真题演练（标准动作，数二数三同题）。下面这道把题干反过来给：先告诉你Q 的第1 列是什么，\n让你倒推参数a，再补全Q。它占2 个解答题位（数二23 ／数三21），是本讲最该先做的一道。",
