        "第2步：二、求特征值．把a = 2 代回：\nA =\n\n\n\n\n1\n−4\n−1\n−4\n2\n\n\n\n.\n算特征多项式（先作行变换制造公因子，比硬展开干净）：\n|λE −A| =\nλ −2\n−1\n−1\nλ + 1\n−1\n−1\nλ −2\nr1−r3\n==\nλ −6\n6 −λ\n−1\nλ + 1\n−1\n−1\nλ −2\n= (λ −6)\n0\n−1\n−1\nλ + 1\n−1\n−1\nλ −2\nc3+c1\n== (λ −6)\n0\n−1\nλ + 1\n−2\n−1\nλ + 2\n= (λ −6)\nλ + 1\n−2\n−1\nλ + 2\n= (λ −6) [(λ + 1)(λ + 2) −2]\n= (λ −6)\nλ2 + 3λ\n\n= λ(λ −6)(λ + 3).\n故特征值为\nλ1 = 6,\nλ2 = −3,\nλ3 = 0.\n（核对：tr A = 2 −1 + 2 = 3 = 6 −3 + 0，吻合；且确有λ3 = 0，与第一步一致。",
        "第3步：）\n三、求特征向量．\nλ1 = 6：解(A −6E)x = 0，\nA −6E =\n\n\n\n\n−4\n−4\n−7\n−4\n−4\n\n\n\n.\n第一、三行相同。",
        "第4步：由r1+4r2：(−4+4)x1+(1−28)x2+(−4+4)x3 = −27x2 = 0，得x2 = 0；代入第\n二行得x1+x3 = 0。"
