      "pitfall": "含参正交变换题的开局永远是这一句：题目透露的标准形信息（项数、某个系数、秩）先翻译\n成对特征值的约束，用P λi = tr A、Q λi = |A| 把参数解出来，再进入求Q 的流程。不要先\n硬展开含参的三次特征多项式——那条路在考场上算不完。\n定理/ 公式52.3 配方法\n• 若含某个平方项x2\n1：把所有含x1 的项集中配成完全平方，剩下的项不再含x1，对剩余变\n量重复。\n• 若不含任何平方项（如f = x1x2 + · · · ）：先做换元\nx1 = y1 + y2,\nx2 = y1 −y2,\nxi = yi (i ≥3),\n制造出平方项y2\n1 −y2\n2，再按上一条配方。\n配方得到的C 只需可逆，不必正交；但最后一定要把变换矩阵C 写出来，配完方就收笔是\n这条路线最常见的丢分。\n真题演练（路线二：配方法的标准题）。2023 数一这道不给标准形，直接问“能否把f 变成g”，\n正是配方法的主场。先想怎么反推：要造出变换，就让两边各自配成平方和，再令两组平方项逐\n项相等，反解出x 与y 的关系——全程不需要特征值。第二问换成正交变换，那就回到上一节的\n表：改用特征值这把尺子。",
