      "content": "设随机变量 $X$ 的概率分布为\n$$\nP\\{X=k\\}=\\frac{1}{2^{k+1}}+\\frac{1}{3^k},\n\\qquad k=1,2,\\ldots\n$$\n则对于正整数 $m,n$，有（ ）。",
