        "解法二：分解为两个几何分布并使用无记忆性。",
        "设 $Y,Z$ 分别服从取值为 $1,2,\\ldots$ 的几何分布，且\n$$\nP\\{Y=k\\}=\\frac{1}{2^k},\n\\qquad\nP\\{Z=k\\}=\\frac{2}{3^k}.\n$$\n则\n$$\nP\\{X=k\\}\n=\\frac12P\\{Y=k\\}+\\frac12P\\{Z=k\\},\n$$\n所以 $X$ 是 $Y$ 与 $Z$ 的等权混合分布。二者的尾概率分别为\n$$\nP\\{Y>j\\}=2^{-j},\n\\qquad\nP\\{Z>j\\}=3^{-j}.\n$$\n在已知 $X>m$ 的条件下，样本来自 $Y$ 分量的后验权重为\n$$\nw_m\n=\\frac{\\frac12P\\{Y>m\\}}\n{\\frac12P\\{Y>m\\}+\\frac12P\\{Z>m\\}}\n=\\frac{2^{-m}}{2^{-m}+3^{-m}}\n>\\frac12.\n$$\n利用几何分布的无记忆性，\n$$\nP\\{X>m+n\\mid X>m\\}\n=w_m2^{-n}+(1-w_m)3^{-n}.\n$$\n而\n$$\nP\\{X>n\\}\n=\\frac12\\,2^{-n}+\\frac12\\,3^{-n}.\n$$\n由于 $w_m>\\dfrac12$ 且 $2^{-n}>3^{-n}$，故\n$$\nP\\{X>m+n\\mid X>m\\}>P\\{X>n\\}.\n$$\n因此选 D。"
