        "4. 验算（用第（I）问的密度直接积分）． E Y = ˆ 1 y · 3 4 dy + ˆ 2 y · 1 4 dy = 3 4 · 1 2 + 1 4 · 4 −1 = 3 8 + 3 8 = 3 4, 与全期望公式一致。故E Y = 3 4。"
