      "content": "设随机变量 $X$ 服从参数为 $1$ 的泊松分布，随机变量 $Y$ 服从参数为 $3$ 的泊松分布，$X$ 与 $Y-X$ 相互独立，则 $E(XY)=\\underline{\\hspace{3em}}$。",
