      "difficulty": "★★★★☆",
      "source": "2025年·数一三（一22、三22）",
      "content": "设投保人的损失事件发生时，保险公司的赔付额 $Y$ 与投保人的损失额 $X$ 的关系为 $Y=\\begin{cases}0,&X\\le100,\\\\X-100,&X\\gt100,\n\\end{cases}$ 设损失事件发生时，投保人的损失额 $X$ 概率密度为 $f(x)=\\begin{cases}\\dfrac{2\\cdot100^2}{(100+x)^3},&x\\gt0,\\\\0,&x\\le0.\n\\end{cases}$（1）求 $P\\{Y\\gt0\\}$ 及 $EY$；（2）这种损失事件在一年内发生的次数记为 $N$，保险公司在一年内就这种损失事件产生的理赔次数记为 $M$。假设 $N$ 服从参数为 $8$ 的泊松分布，在 $N=n$（$n\\ge1$）的条件下，$M$ 服从二项分布 $B(n,p)$，其中 $p=P\\{Y\\gt0\\}$，求 $M$ 的概率分布。",
      "answer": "$P\\{Y\\gt0\\}=\\dfrac14$，$EY=50$；$M\\sim P(2)$，即 $P\\{M=m\\}=e^{-2}\\dfrac{2^m}{m!}$，$m=0,1,2,\\cdots$。",
      "analysis": "考查知识点：数一 / 2025。",
      "solutionSteps": [
        "（1）由赔付规则，$Y>0$ 当且仅当 $X>100$，故\n$$\n\\begin{aligned}\nP\\{Y>0\\}\n&=P\\{X>100\\}\\\\\n&=\\int_{100}^{+\\infty}\\frac{20000}{(100+x)^3}\\,dx\\\\\n&=\\frac14.\n\\end{aligned}\n$$",
        "又\n$$\n\\begin{aligned}\nEY\n&=\\int_{100}^{+\\infty}(x-100)\n\\frac{20000}{(100+x)^3}\\,dx.\n\\end{aligned}\n$$\n令 $u=x+100$，则\n$$\n\\begin{aligned}\nEY\n&=20000\\int_{200}^{+\\infty}\n\\left(\\frac1{u^2}-\\frac{200}{u^3}\\right)\\,du\\\\\n&=20000\\left[\n-\\frac1u+\\frac{100}{u^2}\n\\right]_{200}^{+\\infty}\\\\\n&=50.\n\\end{aligned}\n$$",
        "（2）由第（1）问，\n$$\np=P\\{Y>0\\}=\\frac14.\n$$\n对任意非负整数 $m$，由全概率公式，\n$$\nP\\{M=m\\}\n=\\sum_{n=m}^{+\\infty}\nP\\{M=m\\mid N=n\\}P\\{N=n\\}.\n$$\n由于\n$$\nM\\mid(N=n)\\sim B(n,p),\n\\qquad\nN\\sim P(8),\n$$\n所以\n$$\n\\begin{aligned}\nP\\{M=m\\}\n&=\\sum_{n=m}^{+\\infty}\n\\binom{n}{m}p^m(1-p)^{n-m}\ne^{-8}\\frac{8^n}{n!}\\\\\n&=e^{-8}\\frac{(8p)^m}{m!}\n\\sum_{n=m}^{+\\infty}\n\\frac{[8(1-p)]^{n-m}}{(n-m)!}.\n\\end{aligned}\n$$\n令 $k=n-m$，则\n$$\n\\begin{aligned}\nP\\{M=m\\}\n&=e^{-8}\\frac{(8p)^m}{m!}\n\\sum_{k=0}^{+\\infty}\\frac{[8(1-p)]^k}{k!}\\\\\n&=e^{-8}\\frac{(8p)^m}{m!}e^{8(1-p)}\\\\\n&=e^{-8p}\\frac{(8p)^m}{m!}.\n\\end{aligned}\n$$\n代入 $p=\\frac14$，得到\n$$\nP\\{M=m\\}\n=e^{-2}\\frac{2^m}{m!},\n\\qquad\nm=0,1,2,\\ldots.\n$$\n因此 $M$ 服从参数为 $2$ 的泊松分布。"
      ],
      "pitfall": "注意审题条件与运算符号，规避常见计算失误。",
      "verified": true
