      "pitfall": "第4 步是最大似然的唯一难点。典型情形：总体为U(0, θ)，则\nL(θ) = 1\nθn\n(要求θ ≥max\ni\nxi),\n关于θ 严格递减，求导恒为负、无驻点。因此L 在θ 取最小允许值时最大，得ˆθ\n=\nmax{X1, . . . , Xn}。\n识别信号：均匀分布，或密度的定义域依赖参数。看到就别求导，改判单调性。方向由约束决\n定，不要背结论：约束是θ ≥max xi 就取max，约束是θ ≤min xi 就取min。\n真题演练（边界型，2015 年数一、数三同题）。总体是U(θ, 1)，参数在左端点——所以答案是\nmin 而不是max。凡是背“均匀分布的MLE 是样本最大值”的人，这道题必错：",
