      "answer": "详见具体步骤解析",
      "pitfall": "把这两道对照着看，第4 步的判断就固定下来了：先写出约束不等式，再看L 朝哪个方向单\n调，两者一夹，端点自己就跳出来了。纯粹的边界型MLE 在17 年里只出现过这一次（2015），\n但“样本最大值／最小值”这个对象在2016 与2024 两年的题里又各出现一次（见62.3），所\n以FX(n)(x) = [F(x)]n 这条一定要顺手。\n进阶：带绝对值、双样本、以及2026 年的新包装\n进阶一（难度4，2018 年数一、数三同题）。拉普拉斯分布f =\n2σe−|x|/σ。绝对值不影响求导\n——因为ln L 里|xi| 是已知常数，对σ 求导时它就是个系数。第(II) 问顺势考Eˆσ、Dˆσ，把本讲\n和L59 串了起来：",
