      "difficulty": "★★★★☆",
      "source": "2026年·数一三（一22、三22）",
      "content": "假设某种元件寿命服从指数分布，其均值 $\\theta$ 是未知参数。为估计 $\\theta$，取 $n$ 个这种元件同时做寿命试验，试验直到出现 $k$（$1\\le k\\le n$）个元件失效时停止。（1）若 $k=1$，失效元件寿命记为 $T$，(i) 求 $T$ 的概率密度；(ii) 确定 $a$，使 $\\hat\\theta=aT$ 是 $\\theta$ 的无偏估计，并求 $D(\\hat\\theta)$；（2）已知 $k$ 个失效元件的寿命值分别为 $t_1,t_2,\\cdots,t_k$，且 $t_1\\le t_2\\le\\cdots\\le t_k$，似然函数为 \n$$\nL(\\theta)=\\frac1{\\theta^k}e^{-\\frac1\\theta\\left[\\sum_{i=1}^k t_i+(n-k)t_k\\right]},\n$$\n 求 $\\theta$ 的最大似然估计值。",
      "answer": "（1）$f_T(t)=\\dfrac n\\theta e^{-nt/\\theta}$，$t\\gt0$；$a=n$，$D(\\hat\\theta)=\\theta^2$。 （2）$\\hat\\theta=\\dfrac{\\sum_{i=1}^k t_i+(n-k)t_k}{k}$。",
      "analysis": "考查知识点：数一 / 2026。 设 $X_1,X_2,\\ldots,X_n$ 分别表示 $n$ 个元件的寿命，则它们相互独立，且均服从均值为 $\\theta$ 的指数分布。因此，对 $t\\ge0$，\n$$\nP(X_i>t)=e^{-t/\\theta}.\n$$",
