        "（2）记\n$$\nS=\\sum_{i=1}^kt_i+(n-k)t_k.\n$$\n由于 $\\theta>0$，对数似然函数为\n$$\n\\ell(\\theta)=\\ln L(\\theta)=-k\\ln\\theta-\\frac S\\theta.\n$$\n求导得\n$$\n\\ell'(\\theta)=-\\frac k\\theta+\\frac S{\\theta^2}\n=\\frac{S-k\\theta}{\\theta^2}.\n$$\n当 $0<\\theta<S/k$ 时，$\\ell'(\\theta)>0$；当 $\\theta>S/k$ 时，$\\ell'(\\theta)<0$。因此 $\\ell(\\theta)$ 在 $\\theta=S/k$ 处取得唯一最大值，故最大似然估计值为\n$$\n\\widehat\\theta\n=\\frac Sk\n=\\frac{\\displaystyle\\sum_{i=1}^kt_i+(n-k)t_k}{k}.\n$$"
