      "content": "设函数 $f(x)$ 在 $[-a,a]$ 上具有二阶连续导数。证明：（1）若 $f(0)=0$，则存在 $\\xi\\in(-a,a)$，使得 $f''(\\xi)=\\dfrac1{a^2}[f(a)+f(-a)]$；（2）若 $f(x)$ 在 $(-a,a)$ 内取得极值，则存在 $\\eta\\in(-a,a)$，使得 $|f''(\\eta)|\\ge\\dfrac1{2a^2}|f(a)-f(-a)|$。",
      "answer": "见解析。",
      "analysis": "考查知识点：数一 / 2023。",
      "solutionSteps": [
        "（1）由二阶 Taylor 公式，存在 $\\xi_1\\in(0,a)$，$\\xi_2\\in(-a,0)$，使得 \n$$\nf(a)=f(0)+af'(0)+\\frac{a^2}{2}f''(\\xi_1),\n$$\n \n$$\nf(-a)=f(0)-af'(0)+\\frac{a^2}{2}f''(\\xi_2).\n$$\n 因 $f(0)=0$，两式相加得 \n$$\nf(a)+f(-a)=\\frac{a^2}{2}[f''(\\xi_1)+f''(\\xi_2)].\n$$\n 由 $f''$ 连续及介值定理，存在 $\\xi\\in(-a,a)$，使 \n$$\nf''(\\xi)=\\frac{f(a)+f(-a)}{a^2}.\n$$\n （2）设 $f$ 在 $c\\in(-a,a)$ 处取得极值，则 $f'(c)=0$。令 $M=\\max_{[-a,a]}|f''(x)|$。由 $f'(x)-f'(c)=\\int_c^x f''(t)\\,dt$，得 $|f'(x)|\\le M|x-c|$。于是 \n$$\n|f(a)-f(-a)|\\le\\int_{-a}^{a}|f'(x)|dx\\le M\\int_{-a}^{a}|x-c|dx=M(a^2+c^2)\\le2Ma^2.\n$$\n 故 $M\\ge\\dfrac{|f(a)-f(-a)|}{2a^2}$。由于 $|f''|$ 在闭区间上取到最大值，存在 $\\eta\\in(-a,a)$ 使结论成立。"
      ],
