      "content": "已知 \n$$\nf(x)=\\begin{vmatrix}2x+1&3&2x+1&1\\\\2x&-3&4x&-2\\\\2x+1&2&2x+1&1\\\\2x&-4&4x&-2\\end{vmatrix},\\  g(x)=\\begin{vmatrix}2x+1&1&2x+1&3\\\\5x+1&-2&4x&-3\\\\0&1&2x+1&2\\\\2x&-2&4x&-4\\end{vmatrix},\n$$\n 则方程 $f(x)=g(x)$ 的不同实根个数为 $\\underline{\\hspace{3em}}$。",
